fn trace_tags_for(
    action_class: Option<ActionClass>,
    success: bool,
    tool_name: &str,
    body: &str,
) -> Vec<String> {
    let mut tags = Vec::new();
    tags.push(if success {
        "tool_success".to_string()
    } else {
        "tool_failure".to_string()
    });
    if !success && text_mentions_tool_runtime_bootstrap_failure(body) {
        tags.push("tool_runtime_bootstrap_failure".to_string());
    }
    match action_class {
        Some(ActionClass::Build | ActionClass::Test) if is_local_validator_infra_failure(body) => {
            tags.push("validator_infra_failure".to_string());
        }
        Some(ActionClass::Build | ActionClass::Test)
            if success && validation_output_supports_successful_tool_result(body) =>
        {
            tags.push("validator_success".to_string());
        }
        Some(ActionClass::Build | ActionClass::Test)
            if success && !validation_output_indicates_failure(body) =>
        {
            tags.push("validator_unconfirmed".to_string());
        }
        Some(ActionClass::Build | ActionClass::Test) => {
            tags.push("validator_failure".to_string());
        }
        Some(ActionClass::Unknown) | None if looks_like_shell_tool(tool_name) => {
            tags.push("unclassified_shell_action".to_string());
        }
        Some(ActionClass::Unknown) | None => {
            tags.push("unclassified_tool_action".to_string());
        }
        _ => {}
    }
    tags
}

fn is_local_validator_infra_failure(body: &str) -> bool {
    text_mentions_local_validator_infra_failure(body)
}

fn validation_output_indicates_failure(text: &str) -> bool {
    let text = text.to_ascii_lowercase();
    let strong_failure_markers = [
        "no source files found",
        "filenotfounderror",
        "assertionerror",
        "traceback",
        "failed",
        "failure",
        "error:",
        "no such file",
        "not found",
        "0 passed",
        "no tests ran",
        "recovered 0 rows",
    ];
    strong_failure_markers
        .iter()
        .any(|marker| text.contains(marker))
}

fn validation_output_indicates_success(text: &str) -> bool {
    let text = text.to_ascii_lowercase();
    let strong_success_markers = [
        "validation passed",
        "tests passed",
        "test passed",
        "pytest passed",
        " passed in ",
        " passed,",
        " passed\n",
        " passed\r\n",
        "validator_tests_completed=true",
        "validator_lifecycle_stage=tests_completed",
        "validator_success",
    ];
    strong_success_markers
        .iter()
        .any(|marker| text.contains(marker))
}

fn validation_output_is_unconfirmed_diagnostic(text: &str) -> bool {
    let text = text.to_ascii_lowercase();
    text.contains("outputreferencev1")
        && !validation_output_indicates_success(&text)
        && (text.contains("diagnostic payload") || text.contains("emit_large_log"))
}

fn validation_output_supports_successful_tool_result(text: &str) -> bool {
    !validation_output_indicates_failure(text) && !validation_output_is_unconfirmed_diagnostic(text)
}

fn sanitize_trace_tags(tags: Vec<String>) -> Vec<String> {
    tags.into_iter()
        .filter(|tag| is_known_trace_tag(tag))
        .collect()
}

fn trace_tag_value<'a>(tags: &'a [String], key: &str) -> Option<&'a str> {
    let prefix = format!("{key}:");
    tags.iter()
        .find_map(|tag| tag.strip_prefix(prefix.as_str()))
}

fn trace_tag_usize(tags: &[String], key: &str) -> Option<usize> {
    trace_tag_value(tags, key).and_then(|value| value.parse::<usize>().ok())
}

fn trace_tag_bool(tags: &[String], key: &str) -> Option<bool> {
    trace_tag_value(tags, key).and_then(|value| value.parse::<bool>().ok())
}

fn map_runtime_event_from_trace_event(event: TaskSpaceTraceEvent) -> MapRuntimeEvent {
    MapRuntimeEvent::TaskspaceTraceEventRecorded(MapRuntimeTraceEventRecordedEvent {
        trace_event_id: event.id,
        kind: event.kind,
        task_id: event.task_id,
        map_id: event.map_id,
        node_id: event.node_id,
        result_id: event.result_id,
        call_id: event.call_id,
        action_class: event.action_class.map(|action| action.as_str().to_string()),
        tool_success: event.tool_success,
        tags: event.tags,
        artifact_refs: event.artifact_refs,
        created_at_ms: event.created_at_ms,
    })
}

fn sanitize_provider_response_trace_tag_value(value: &str) -> String {
    value
        .chars()
        .map(|ch| match ch {
            '\r' | '\n' | '\t' => ' ',
            _ => ch,
        })
        .take(160)
        .collect::<String>()
}

