fn looks_like_shell_tool(tool_name: &str) -> bool {
    let normalized = tool_name.to_ascii_lowercase();
    normalized.contains("shell") || normalized.contains("command")
}

fn snapshot_map(map: &ActionMapInstance) -> ActionMapSnapshotMap {
    let mut nodes = map
        .nodes
        .values()
        .map(|node| ActionMapSnapshotNode {
            id: node.id.clone(),
            title: node.title.clone(),
            kind: node.kind.as_str().to_string(),
            canonical_kind: node.kind.canonical_kind().to_string(),
            status: node.status.as_str().to_string(),
            context_summary: node.context.summary.clone(),
            source_refs: node.context.source_refs.clone(),
            active_lease: node.active_lease.clone(),
            result_ids: node
                .result_context
                .iter()
                .map(|result| result.id.clone())
                .collect(),
            origin_node_id: node.origin_node_id.clone(),
        })
        .collect::<Vec<_>>();
    nodes.sort_by(|left, right| left.id.cmp(&right.id));

    let mut leases = map
        .leases
        .values()
        .map(|lease| ActionMapSnapshotLease {
            id: lease.id.clone(),
            map_id: lease.map_id.clone(),
            node_id: lease.node_id.clone(),
            holder: lease.holder.as_str().to_string(),
            previous_node_status: lease.previous_node_status.as_str().to_string(),
            agent_thread_id: lease.agent_thread_id,
            agent_path: lease.agent_path.clone(),
            subagent_plan_id: lease.subagent_plan_id.clone(),
        })
        .collect::<Vec<_>>();
    leases.sort_by(|left, right| left.id.cmp(&right.id));

    let mut results = map
        .results
        .values()
        .map(|result| ActionMapSnapshotResult {
            id: result.id.clone(),
            assignment_id: result.assignment_id.clone(),
            subagent_plan_id: result.subagent_plan_id.clone(),
            map_id: result.map_id.clone(),
            node_id: result.node_id.clone(),
            kind: result.kind.as_str().to_string(),
            action_class: result.action_class.map(|class| class.as_str().to_string()),
            tool_success: result.tool_success,
            body: result.body.clone(),
            evidence_package: snapshot_evidence_package(&result.evidence_package),
            source_thread_id: result.source_thread_id,
            created_at_ms: result.created_at_ms,
        })
        .collect::<Vec<_>>();
    results.sort_by(|left, right| left.id.cmp(&right.id));

    let mut subagent_plans = map
        .subagent_plans
        .values()
        .map(|plan| ActionMapSnapshotSubagentPlan {
            id: plan.id.clone(),
            task_id: plan.task_id.clone(),
            map_id: plan.map_id.clone(),
            parent_node_id: plan.parent_node_id.clone(),
            why_parallelizable: plan.why_parallelizable.clone(),
            expected_artifact: plan.expected_artifact.clone(),
            acceptance_check: plan.acceptance_check.clone(),
            max_scope: plan.max_scope.clone(),
            supports_questions: plan.supports_questions.clone(),
            tests_hypotheses: plan.tests_hypotheses.clone(),
            depends_on_results: plan.depends_on_results.clone(),
            status: plan.status.as_str().to_string(),
            lease_id: plan.lease_id.clone(),
            child_thread_id: plan.child_thread_id,
            result_ids: plan.result_ids.clone(),
            created_at_ms: plan.created_at_ms,
            updated_at_ms: plan.updated_at_ms,
        })
        .collect::<Vec<_>>();
    subagent_plans.sort_by(|left, right| left.id.cmp(&right.id));

    ActionMapSnapshotMap {
        id: map.id.clone(),
        task_id: map.task_id.clone(),
        title: map.title.clone(),
        status: map.status.as_str().to_string(),
        owner_session_id: map.owner_session_id,
        base_map_version: map.base_map_version.clone(),
        created_from: map.created_from.clone(),
        ready_node_count: map.ready_node_count(),
        running_node_count: map.running_node_count(),
        completed_node_count: map.completed_node_count(),
        nodes,
        edges: map
            .edges
            .iter()
            .map(|edge| ActionMapSnapshotEdge {
                from: edge.from.clone(),
                to: edge.to.clone(),
            })
            .collect(),
        leases,
        results,
        subagent_plans,
    }
}

fn single_line_preview(text: &str, max_chars: usize) -> String {
    let normalized = text.split_whitespace().collect::<Vec<_>>().join(" ");
    if normalized.chars().count() <= max_chars {
        return normalized;
    }
    let mut preview = normalized.chars().take(max_chars).collect::<String>();
    preview.push_str("...");
    preview
}

fn format_node_candidates(map: &ActionMapInstance, node_ids: &[MapNodeId]) -> String {
    node_ids
        .iter()
        .map(|node_id| {
            let title = map
                .nodes
                .get(node_id)
                .map(|node| single_line_preview(&node.title, 80))
                .unwrap_or_default();
            format!("{node_id} ({title})")
        })
        .collect::<Vec<_>>()
        .join(", ")
}

fn refresh_ready_nodes(map: &mut ActionMapInstance) -> Vec<MapRuntimeEvent> {
    if map.status != MapStatus::Active {
        return Vec::new();
    }
    let mut events = Vec::new();
    let pending_ids = map
        .nodes
        .iter()
        .filter_map(|(id, node)| (node.status == NodeStatus::Pending).then_some(id.clone()))
        .collect::<Vec<_>>();
    for node_id in pending_ids {
        let deps = map
            .edges
            .iter()
            .filter(|edge| edge.to == node_id)
            .map(|edge| edge.from.clone())
            .collect::<Vec<_>>();
        let ready = !deps.is_empty()
            && map.nodes.get(&node_id).is_some_and(|node| {
                deps.iter()
                    .all(|dependency_id| node_dependency_ready(map, node, dependency_id))
            });
        if ready && let Some(node) = map.nodes.get_mut(&node_id) {
            let previous_status = node.status;
            node.status = NodeStatus::Ready;
            events.push(node_status_changed_event(
                &map.id,
                &node.id,
                &node.title,
                previous_status,
                node.status,
            ));
        }
    }
    events
}

fn refresh_ready_validation_rework_nodes(
    map: &mut ActionMapInstance,
    validation_node_id: &str,
) -> Vec<MapRuntimeEvent> {
    if map.status != MapStatus::Active
        || !map.nodes.get(validation_node_id).is_some_and(|node| {
            matches!(node.kind, NodeKind::SmokeTest | NodeKind::RegressionTest)
                && node.status == NodeStatus::Blocked
        })
    {
        return Vec::new();
    }
    let mut events = Vec::new();
    let pending_ids = map
        .nodes
        .iter()
        .filter_map(|(id, node)| {
            (node.kind == NodeKind::ImplementSolution
                && node.status == NodeStatus::Pending
                && node.origin_node_id.as_deref() == Some(validation_node_id))
            .then_some(id.clone())
        })
        .collect::<Vec<_>>();
    for node_id in pending_ids {
        let deps = map
            .edges
            .iter()
            .filter(|edge| edge.to == node_id)
            .map(|edge| edge.from.clone())
            .collect::<Vec<_>>();
        let ready = !deps.is_empty()
            && map.nodes.get(&node_id).is_some_and(|node| {
                deps.iter()
                    .all(|dependency_id| node_dependency_ready(map, node, dependency_id))
            });
        if ready && let Some(node) = map.nodes.get_mut(&node_id) {
            let previous_status = node.status;
            node.status = NodeStatus::Ready;
            events.push(node_status_changed_event(
                &map.id,
                &node.id,
                &node.title,
                previous_status,
                node.status,
            ));
        }
    }
    events
}

fn node_dependency_ready(map: &ActionMapInstance, node: &MapNode, dependency_id: &str) -> bool {
    map.nodes.get(dependency_id).is_some_and(|dependency| {
        dependency.status == NodeStatus::Completed
            || new_node_dependency_ready_from_status(
                map,
                node.kind,
                node.origin_node_id.as_deref(),
                dependency_id,
                dependency.status,
            )
    })
}

fn new_node_dependency_ready_from_status(
    map: &ActionMapInstance,
    node_kind: NodeKind,
    origin_node_id: Option<&str>,
    dependency_id: &str,
    dependency_status: NodeStatus,
) -> bool {
    node_kind == NodeKind::ImplementSolution
        && origin_node_id == Some(dependency_id)
        && dependency_status == NodeStatus::Blocked
        && map.nodes.get(dependency_id).is_some_and(|dependency| {
            matches!(
                dependency.kind,
                NodeKind::SmokeTest | NodeKind::RegressionTest
            )
        })
}

fn dependencies_will_be_completed_after_finish(
    map: &ActionMapInstance,
    finishing_node_id: &str,
    target_node_id: &str,
) -> bool {
    let deps = map
        .edges
        .iter()
        .filter(|edge| edge.to == target_node_id)
        .map(|edge| edge.from.as_str())
        .collect::<Vec<_>>();
    !deps.is_empty()
        && deps.iter().all(|dependency_id| {
            *dependency_id == finishing_node_id
                || map
                    .nodes
                    .get(*dependency_id)
                    .is_some_and(|node| node.status == NodeStatus::Completed)
        })
}

fn default_dependency_node_ids_for_new_node(map: &ActionMapInstance) -> Vec<String> {
    let nodes_with_outgoing_edges_to_completed = map
        .edges
        .iter()
        .filter(|edge| {
            map.nodes
                .get(&edge.to)
                .is_some_and(|node| node.status == NodeStatus::Completed)
        })
        .map(|edge| edge.from.as_str())
        .collect::<HashSet<_>>();
    let mut leaf_completed_nodes = map
        .nodes
        .values()
        .filter(|node| {
            node.status == NodeStatus::Completed
                && !nodes_with_outgoing_edges_to_completed.contains(node.id.as_str())
        })
        .map(|node| node.id.clone())
        .collect::<Vec<_>>();
    leaf_completed_nodes.sort();
    leaf_completed_nodes
}

fn pending_inspect_nodes_ready_after_finishing(
    map: &ActionMapInstance,
    finishing_node_id: &str,
) -> Vec<String> {
    let mut node_ids = map
        .nodes
        .values()
        .filter(|node| {
            node.kind == NodeKind::InspectCodeContext
                && node.status == NodeStatus::Pending
                && dependencies_will_be_completed_after_finish(map, finishing_node_id, &node.id)
        })
        .map(|node| node.id.clone())
        .collect::<Vec<_>>();
    node_ids.sort();
    node_ids
}

fn completed_subagent_inspect_node_ids(
    map: &ActionMapInstance,
    owner_session_id: ThreadId,
) -> Vec<String> {
    let mut node_ids = map
        .nodes
        .values()
        .filter(|node| {
            node.kind == NodeKind::InspectCodeContext
                && node.status == NodeStatus::Completed
                && node.result_context.iter().any(|result_ref| {
                    map.results.get(&result_ref.id).is_some_and(|result| {
                        result.source_thread_id != owner_session_id
                            && result.evidence_package.validity == ResultValidity::Accepted
                    })
                })
        })
        .map(|node| node.id.clone())
        .collect::<Vec<_>>();
    node_ids.sort();
    node_ids
}

fn broad_completed_inspect_node_ids(
    map: &ActionMapInstance,
    owner_session_id: ThreadId,
) -> Vec<String> {
    let mut node_ids = map
        .nodes
        .values()
        .filter(|node| {
            node.kind == NodeKind::InspectCodeContext
                && node.status == NodeStatus::Completed
                && completed_main_inspect_has_broad_accepted_result(map, &node.id, owner_session_id)
        })
        .map(|node| node.id.clone())
        .collect::<Vec<_>>();
    node_ids.sort();
    node_ids
}

fn has_unresolved_broad_delegation_debt(
    map: &ActionMapInstance,
    owner_session_id: ThreadId,
) -> bool {
    let broad_completed_inspects = broad_completed_inspect_node_ids(map, owner_session_id);
    !broad_completed_inspects.is_empty()
        && related_completed_accepted_subagent_inspect_node_ids(
            map,
            owner_session_id,
            &broad_completed_inspects,
        )
        .len()
            < 2
}

fn broad_delegation_recovery_message(broad_completed_inspects: &[String]) -> String {
    let message = "TaskSpace blocked ordinary main-agent work because a broad inspect_code_context node exhausted its main-tool budget or produced broad structural findings without two accepted subagent inspect results on dependent investigation tracks. Delegate the remaining independent investigation tracks: create two ready inspect_code_context nodes if needed, record a subagent plan for each ready track, call spawn_agent with explicit node_id for each track, then mark the subagent results accepted before continuing ordinary tools.";
    let blocking_items = broad_completed_inspects
        .iter()
        .map(|node_id| format!("broad_inspect_delegation_debt:{node_id}"))
        .collect::<Vec<_>>();
    gate_recovery_message(
        message,
        "broad_inspect_delegation_debt",
        blocking_items,
        vec![
            "taskspace_control(action=create_node, node_kind=\"inspect_code_context\", bind_current=false) for first independent track".to_string(),
            "taskspace_control(action=create_node, node_kind=\"inspect_code_context\", bind_current=false) for second independent track".to_string(),
            "taskspace_control(action=record_subagent_plan, parent_node_id=\"<ready inspect node>\") for each track".to_string(),
            "spawn_agent(node_id=\"<ready inspect node>\") for each planned track".to_string(),
            "taskspace_control(action=mark_result_validity, status=\"accepted\") for two completed subagent inspect results".to_string(),
        ],
        vec!["two accepted subagent inspect results related to the broad inspect node".to_string()],
    )
}

fn provider_request_budget_pressure_active_for_node(
    _provider_request_count: usize,
    _max_requests: usize,
    _node_kind: NodeKind,
) -> bool {
    false
}

fn provider_request_budget_snapshot_pressure_active_for_node(
    snapshot: &ActionMapProviderRequestBudgetSnapshot,
    _node_kind: NodeKind,
) -> bool {
    let rollout_limit_reached =
        snapshot.max_requests > 0 && snapshot.request_count >= snapshot.max_requests;
    let node_limit_reached = snapshot.max_model_requests_per_node > 0
        && snapshot.node_request_count >= snapshot.max_model_requests_per_node;
    rollout_limit_reached || node_limit_reached
}

fn effective_provider_node_request_limit(
    base_limit: usize,
    task: Option<&TaskState>,
    node: Option<&MapNode>,
) -> usize {
    if !node.is_some_and(|node| node.kind == NodeKind::InspectCodeContext) {
        return base_limit;
    }
    let fact_source_count = task
        .map(task_required_fact_source_artifact_refs)
        .unwrap_or_default()
        .len();
    if fact_source_count == 0 {
        return base_limit;
    }
    base_limit.max(fact_source_count.saturating_mul(2).saturating_add(2))
}

fn budget_state_for_counter(counter_value: usize, counter_limit: usize) -> TaskSpaceBudgetState {
    if counter_limit == 0 || counter_value >= counter_limit {
        return TaskSpaceBudgetState::OverProfileHint;
    }
    let remaining = counter_limit.saturating_sub(counter_value);
    if remaining <= 1 {
        return TaskSpaceBudgetState::CompactCheckpointRequired;
    }
    if counter_value.saturating_mul(4) >= counter_limit.saturating_mul(3) {
        return TaskSpaceBudgetState::ThinDowngraded;
    }
    if counter_value.saturating_mul(2) >= counter_limit {
        return TaskSpaceBudgetState::Warned;
    }
    TaskSpaceBudgetState::Normal
}

fn completed_main_inspect_has_broad_accepted_result(
    map: &ActionMapInstance,
    node_id: &str,
    owner_session_id: ThreadId,
) -> bool {
    map.nodes.get(node_id).is_some_and(|node| {
        node.result_context.iter().any(|result_ref| {
            map.results.get(&result_ref.id).is_some_and(|result| {
                result.kind != NodeResultKind::MainToolCall
                    && result.source_thread_id == owner_session_id
                    && result.evidence_package.validity == ResultValidity::Accepted
                    && accepted_result_has_broad_structural_evidence(result)
            })
        })
    })
}

fn accepted_result_has_broad_structural_evidence(result: &NodeResult) -> bool {
    let artifact_refs = accepted_result_artifact_refs(result);
    let implementation_refs = artifact_refs
        .iter()
        .filter(|artifact_ref| is_implementation_surface_ref(artifact_ref))
        .count();
    result.evidence_package.claims.len() >= 3 && implementation_refs >= 2
}

fn accepted_result_artifact_refs(result: &NodeResult) -> HashSet<String> {
    let mut artifact_refs = HashSet::new();
    for evidence_ref in &result.evidence_package.evidence_refs {
        if let Some(artifact_ref) = evidence_ref.artifact_ref.as_deref() {
            let artifact_ref = artifact_ref.trim();
            if !artifact_ref.is_empty() {
                artifact_refs.insert(artifact_ref.to_ascii_lowercase());
            }
        }
    }
    for claim in &result.evidence_package.claims {
        for evidence_ref in &claim.evidence_refs {
            if let Some(artifact_ref) = evidence_ref.artifact_ref.as_deref() {
                let artifact_ref = artifact_ref.trim();
                if !artifact_ref.is_empty() {
                    artifact_refs.insert(artifact_ref.to_ascii_lowercase());
                }
            }
        }
    }
    artifact_refs
}

fn node_result_evidence_package_for_artifact_refs(
    artifact_refs: &[String],
) -> NodeResultEvidencePackage {
    if artifact_refs.is_empty() {
        return NodeResultEvidencePackage::default();
    }
    NodeResultEvidencePackage {
        evidence_refs: artifact_refs
            .iter()
            .map(|artifact_ref| EvidenceRef {
                artifact_ref: Some(artifact_ref.clone()),
                ..Default::default()
            })
            .collect(),
        ..Default::default()
    }
}

fn merge_artifact_refs(mut left: Vec<String>, right: Vec<String>) -> Vec<String> {
    for artifact in right {
        if !left.iter().any(|existing| existing == &artifact) {
            left.push(artifact);
        }
    }
    left
}

fn tool_action_descriptor_artifact_refs(descriptor: &ToolActionDescriptor) -> Vec<String> {
    match descriptor.action_class {
        ActionClass::Read => descriptor
            .preview
            .parse::<serde_json::Value>()
            .ok()
            .and_then(|value| {
                value
                    .get("command")
                    .and_then(serde_json::Value::as_str)
                    .and_then(read_command_artifact_ref)
            })
            .into_iter()
            .collect(),
        ActionClass::Edit => extract_edit_changed_artifacts_from_tool_body(&descriptor.preview),
        _ => Vec::new(),
    }
}

fn validation_test_coverage_block(
    map: &ActionMapInstance,
    node: &MapNode,
    task: &TaskState,
    descriptor: &ToolActionDescriptor,
) -> Option<(String, String, Vec<String>, Vec<String>)> {
    let command = tool_action_descriptor_command(descriptor)?;
    if let Some(required_validator) = discovered_required_local_validator_commands(map)
        .into_iter()
        .find(|validator| !command_covers_local_validator(&command, validator))
    {
        let reason = "validation_test_missing_local_validator_coverage".to_string();
        let message = format!(
            "TaskSpace blocked this validation command because current node `{}` kind: {} has already discovered local validator `{}` but requested command `{}` does not run it. Unit tests such as pytest may pass while the local validator still fails. Run the discovered validator before closing validation.",
            node.id,
            node.kind.as_str(),
            required_validator,
            single_line_preview(&command, 220)
        );
        let next_valid_actions = vec![format!(
            "run_test with command `{required_validator}` to execute the discovered local validator"
        )];
        let evidence_refs = vec![
            format!("current_node:{}:{}", node.id, node.kind.as_str()),
            format!("required_validator:{required_validator}"),
        ];
        return Some((reason, message, next_valid_actions, evidence_refs));
    }
    if command_is_general_validation_runner(&command) {
        return None;
    }
    let changed_artifacts = validation_dependency_changed_artifacts(map, node);
    let output_targets = task_output_contract_artifact_targets(task);
    let output_requirements = task_output_contract_validation_requirements(task);
    let changed_artifacts_requiring_coverage = changed_artifacts
        .iter()
        .filter(|artifact| {
            !output_targets
                .iter()
                .any(|output| artifact_refs_equivalent(artifact, output))
        })
        .cloned()
        .collect::<Vec<_>>();
    let covered_changed_artifact = if changed_artifacts_requiring_coverage.is_empty() {
        changed_artifacts
            .iter()
            .any(|artifact| command_mentions_artifact(&command, artifact))
            || command_invokes_script_artifact(&command)
            || output_targets
                .iter()
                .any(|artifact| command_mentions_artifact(&command, artifact))
    } else {
        changed_artifacts_requiring_coverage
            .iter()
            .any(|artifact| command_mentions_artifact(&command, artifact))
            || command_invokes_script_artifact(&command)
    };
    if changed_artifacts.is_empty() || covered_changed_artifact {
        if let Some(block) = validation_output_contract_coverage_block_for_command(
            map,
            node,
            &changed_artifacts,
            &output_requirements,
            &command,
        ) {
            return Some((
                block.reason,
                block.message,
                block.next_valid_actions,
                block.evidence_refs,
            ));
        }
        return None;
    }
    let changed_summary = changed_artifacts
        .iter()
        .take(4)
        .cloned()
        .collect::<Vec<_>>()
        .join(", ");
    let output_summary = if output_targets.is_empty() {
        "none recorded".to_string()
    } else {
        output_targets
            .iter()
            .take(4)
            .cloned()
            .collect::<Vec<_>>()
            .join(", ")
    };
    let reason = "validation_test_missing_changed_artifact_coverage".to_string();
    let message = format!(
        "TaskSpace blocked this validation command because current node `{}` kind: {} must validate the implementation edit, but requested command `{}` does not execute or reference changed artifact(s): {}. Declared output contract targets: {}. Run the changed artifact directly, run a real project/official validator such as pytest or run-tests, or block with the exact reason validation cannot exercise the edit. Do not run discovery commands such as find, ls, rg, or Get-ChildItem to rediscover the changed artifact; it is already known.",
        node.id,
        node.kind.as_str(),
        single_line_preview(&command, 220),
        changed_summary,
        output_summary
    );
    let mut next_valid_actions = changed_artifacts
        .iter()
        .take(3)
        .map(|artifact| validation_changed_artifact_action(artifact))
        .collect::<Vec<_>>();
    next_valid_actions.push("or run a real project/official validator command such as pytest, cargo test, npm test, or run-tests".to_string());
    let mut evidence_refs = vec![format!("current_node:{}:{}", node.id, node.kind.as_str())];
    evidence_refs.extend(
        changed_artifacts
            .iter()
            .take(4)
            .map(|artifact| format!("changed_artifact:{artifact}")),
    );
    evidence_refs.extend(
        output_targets
            .iter()
            .take(4)
            .map(|artifact| format!("output_contract:{artifact}")),
    );
    Some((reason, message, next_valid_actions, evidence_refs))
}

#[derive(Debug, Clone, Default, PartialEq, Eq)]
struct OutputContractValidationRequirements {
    targets: Vec<String>,
    schema_targets: Vec<String>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct ValidationCoverageBlock {
    result_id: Option<String>,
    reason: String,
    message: String,
    next_valid_actions: Vec<String>,
    evidence_refs: Vec<String>,
}

fn validation_node_output_contract_coverage_block(
    map: &ActionMapInstance,
    node: &MapNode,
    task: &TaskState,
) -> Option<ValidationCoverageBlock> {
    let requirements = task_output_contract_validation_requirements(task);
    let changed_artifacts = validation_dependency_changed_artifacts(map, node);
    let result = latest_successful_validation_result(map, node)?;
    let command = result_body_command(result).unwrap_or_default();
    if command.trim().is_empty()
        && output_contract_targets_are_changed_artifacts(&requirements, &changed_artifacts)
        && validation_result_body_has_output_value(&result.body)
    {
        return None;
    }
    if command.trim().is_empty() && validation_result_body_confirms_general_validator(&result.body)
    {
        return None;
    }
    validation_output_contract_coverage_block_for_command(
        map,
        node,
        &changed_artifacts,
        &requirements,
        &command,
    )
    .map(|mut block| {
        block.result_id = Some(result.id.clone());
        block
    })
}

fn latest_successful_validation_result<'a>(
    map: &'a ActionMapInstance,
    node: &'a MapNode,
) -> Option<&'a NodeResult> {
    node.result_context.iter().rev().find_map(|result_ref| {
        let result = map.results.get(&result_ref.id)?;
        node_result_is_successful_validation(result).then_some(result)
    })
}

fn validation_output_contract_coverage_block_for_command(
    map: &ActionMapInstance,
    node: &MapNode,
    changed_artifacts: &[String],
    requirements: &OutputContractValidationRequirements,
    command: &str,
) -> Option<ValidationCoverageBlock> {
    let requirements =
        output_contract_requirements_for_validation_command(requirements, changed_artifacts);
    if requirements.targets.is_empty()
        || command_is_general_validation_runner(command)
        || command_validates_output_contract_targets(command, &requirements)
    {
        return None;
    }
    let target_summary = summarize_artifact_refs(&requirements.targets);
    let schema_summary = if requirements.schema_targets.is_empty() {
        "none recorded".to_string()
    } else {
        summarize_artifact_refs(&requirements.schema_targets)
    };
    let reason = "validation_test_missing_output_contract_coverage".to_string();
    let message = format!(
        "TaskSpace blocked this validation command because current node `{}` kind: {} has declared output contract artifact(s): {}, schema/validator artifact(s): {}, but requested command `{}` does not validate those output contract(s). Running a generator or changed script with exit code 0 only proves execution; it does not prove the produced artifact satisfies the declared format/schema/validator contract.",
        node.id,
        node.kind.as_str(),
        target_summary,
        schema_summary,
        single_line_preview(command, 220)
    );
    let next_valid_actions =
        validation_output_contract_next_actions(changed_artifacts, &requirements);
    let mut evidence_refs = vec![format!("current_node:{}:{}", node.id, node.kind.as_str())];
    evidence_refs.extend(
        changed_artifacts
            .iter()
            .take(4)
            .map(|artifact| format!("changed_artifact:{artifact}")),
    );
    evidence_refs.extend(
        requirements
            .targets
            .iter()
            .take(4)
            .map(|artifact| format!("output_contract:{artifact}")),
    );
    for event in map
        .task_id
        .iter()
        .map(|task_id| format!("task:{task_id}"))
        .take(1)
    {
        evidence_refs.push(event);
    }
    Some(ValidationCoverageBlock {
        result_id: None,
        reason,
        message,
        next_valid_actions,
        evidence_refs,
    })
}

fn task_output_contract_validation_requirements(
    task: &TaskState,
) -> OutputContractValidationRequirements {
    let mut requirements = OutputContractValidationRequirements::default();
    for contract in &task.cognitive_state.output_contracts {
        for value in [&contract.id, &contract.description] {
            for artifact in extract_artifact_like_refs(value) {
                push_output_contract_validation_target(&mut requirements, &artifact, contract.kind);
            }
        }
        for evidence in &contract.evidence_refs {
            if let Some(artifact) = evidence.artifact_ref.as_deref() {
                push_output_contract_validation_target(
                    &mut requirements,
                    &normalize_artifact_ref(artifact),
                    contract.kind,
                );
            }
        }
    }
    for criterion in &task.problem_ledger.success_criteria {
        push_success_criterion_validation_requirements(
            &mut requirements,
            &criterion.description,
            &criterion.evidence_refs,
        );
    }
    for criterion in &task.cognitive_state.success_criteria {
        push_success_criterion_validation_requirements(&mut requirements, criterion, &[]);
    }
    for source in &task.cognitive_state.fact_sources {
        if fact_source_is_optional(source) {
            continue;
        }
        for value in [&source.id, &source.description] {
            for artifact in extract_artifact_like_refs(value) {
                push_output_contract_schema_or_validator_requirement(&mut requirements, &artifact);
            }
        }
        for evidence in &source.evidence_refs {
            if let Some(artifact) = evidence.artifact_ref.as_deref() {
                push_output_contract_schema_or_validator_requirement(
                    &mut requirements,
                    &normalize_artifact_ref(artifact),
                );
            }
        }
    }
    requirements
}

fn push_output_contract_validation_target(
    requirements: &mut OutputContractValidationRequirements,
    artifact: &str,
    kind: OutputContractKind,
) {
    let artifact = normalize_artifact_ref(artifact);
    if !output_contract_validation_artifact_ref(&artifact) {
        return;
    }
    push_unique_artifact_ref(&mut requirements.targets, artifact.clone());
    if output_contract_schema_or_validator_target(&artifact, kind) {
        push_unique_artifact_ref(&mut requirements.schema_targets, artifact);
    }
}

fn push_output_contract_schema_or_validator_requirement(
    requirements: &mut OutputContractValidationRequirements,
    artifact: &str,
) {
    let artifact = normalize_artifact_ref(artifact);
    if !output_contract_validation_artifact_ref(&artifact)
        || !output_contract_artifact_ref_looks_like_schema_or_validator(&artifact)
    {
        return;
    }
    push_unique_artifact_ref(&mut requirements.schema_targets, artifact);
}

fn push_success_criterion_validation_requirement(
    requirements: &mut OutputContractValidationRequirements,
    artifact: &str,
) {
    let artifact = normalize_artifact_ref(artifact);
    if !output_contract_validation_artifact_ref(&artifact) {
        return;
    }
    if output_contract_artifact_ref_looks_like_schema_or_validator(&artifact) {
        push_unique_artifact_ref(&mut requirements.schema_targets, artifact);
        return;
    }
    if output_contract_artifact_ref_looks_like_generated_json_output(&artifact) {
        push_unique_artifact_ref(&mut requirements.targets, artifact);
    }
}

fn push_success_criterion_validation_requirements(
    requirements: &mut OutputContractValidationRequirements,
    description: &str,
    evidence_refs: &[EvidenceRef],
) {
    for artifact in extract_artifact_like_refs(description) {
        push_success_criterion_validation_requirement(requirements, &artifact);
    }
    for evidence in evidence_refs {
        if let Some(artifact_ref) = evidence.artifact_ref.as_deref() {
            push_success_criterion_validation_requirement(
                requirements,
                &normalize_artifact_ref(artifact_ref),
            );
        }
    }
}

fn output_contract_validation_artifact_ref(artifact: &str) -> bool {
    let normalized = normalize_artifact_ref(artifact);
    let lower = normalized.to_ascii_lowercase();
    if lower.is_empty()
        || lower.contains("://")
        || lower.starts_with("test-fixture:")
        || lower.starts_with("output-ref:")
        || lower.starts_with("validator:")
    {
        return false;
    }
    artifact_like_token(&normalized)
}

fn output_contract_artifact_ref_looks_like_generated_json_output(artifact: &str) -> bool {
    let lower = normalize_artifact_ref(artifact).to_ascii_lowercase();
    let file = lower.rsplit('/').next().unwrap_or(lower.as_str());
    file.ends_with(".json") && !output_contract_artifact_ref_looks_like_schema_or_validator(file)
}

fn output_contract_schema_or_validator_target(artifact: &str, kind: OutputContractKind) -> bool {
    matches!(
        kind,
        OutputContractKind::Schema | OutputContractKind::Validator
    ) || artifact
        .rsplit('/')
        .next()
        .unwrap_or(artifact)
        .to_ascii_lowercase()
        .contains("schema")
}

fn output_contract_artifact_ref_looks_like_schema_or_validator(artifact: &str) -> bool {
    let lower = normalize_artifact_ref(artifact).to_ascii_lowercase();
    let file = lower.rsplit('/').next().unwrap_or(lower.as_str());
    file.contains("schema")
        || file.contains("validator")
        || file.contains("validate")
        || file == "run-tests.sh"
        || file == "run_tests.sh"
        || lower.contains("/tests/")
        || lower.contains("\\tests\\")
        || file.starts_with("test_")
        || file.ends_with("_test.py")
        || file.ends_with(".test.js")
        || file.ends_with(".spec.js")
}

fn command_validates_output_contract_targets(
    command: &str,
    requirements: &OutputContractValidationRequirements,
) -> bool {
    if requirements.targets.is_empty() {
        return true;
    }
    if command_is_general_validation_runner(command) {
        return true;
    }
    let mentions_output_target = requirements
        .targets
        .iter()
        .any(|target| command_mentions_artifact(command, target));
    if !mentions_output_target {
        return false;
    }
    if !requirements.schema_targets.is_empty() {
        return requirements
            .schema_targets
            .iter()
            .any(|target| command_mentions_artifact(command, target))
            && command_has_schema_or_validator_check_semantics(command);
    }
    command_has_output_validation_check_semantics(command)
}

fn output_contract_requirements_for_validation_command(
    requirements: &OutputContractValidationRequirements,
    changed_artifacts: &[String],
) -> OutputContractValidationRequirements {
    let removable_changed_scripts = requirements
        .targets
        .iter()
        .filter(|target| {
            script_artifact_token(target)
                && changed_artifacts
                    .iter()
                    .any(|artifact| artifact_refs_match(artifact, target))
        })
        .cloned()
        .collect::<Vec<_>>();
    if removable_changed_scripts.is_empty()
        || removable_changed_scripts.len() >= requirements.targets.len()
    {
        return requirements.clone();
    }
    let targets = requirements
        .targets
        .iter()
        .filter(|target| {
            !removable_changed_scripts
                .iter()
                .any(|script| artifact_refs_match(script, target))
        })
        .cloned()
        .collect::<Vec<_>>();
    let schema_targets = requirements
        .schema_targets
        .iter()
        .filter(|schema| {
            !removable_changed_scripts
                .iter()
                .any(|script| artifact_refs_match(script, schema))
        })
        .cloned()
        .collect::<Vec<_>>();
    OutputContractValidationRequirements {
        targets,
        schema_targets,
    }
}

fn output_contract_targets_are_changed_artifacts(
    requirements: &OutputContractValidationRequirements,
    changed_artifacts: &[String],
) -> bool {
    !requirements.targets.is_empty()
        && requirements.targets.iter().all(|target| {
            changed_artifacts
                .iter()
                .any(|artifact| artifact_refs_match(artifact, target))
        })
}

fn validation_result_body_has_output_value(body: &str) -> bool {
    let lower = body.to_ascii_lowercase();
    lower
        .split_once("output:")
        .map(|(_, output)| !output.trim().is_empty())
        .unwrap_or(false)
}

fn command_has_output_validation_check_semantics(command: &str) -> bool {
    let lower = command.to_ascii_lowercase();
    [
        "assert",
        "check",
        "cmp ",
        "diff ",
        "grep ",
        "jq ",
        "jsonschema",
        "json.tool",
        "node -e",
        "perl -e",
        "ruby -e",
        "schema",
        "test",
        "validate",
        "validator",
    ]
    .iter()
    .any(|marker| lower.contains(marker))
}

fn command_has_schema_or_validator_check_semantics(command: &str) -> bool {
    let lower = command.to_ascii_lowercase();
    [
        "ajv",
        "draft7validator",
        "jsonschema",
        "pytest",
        "run-tests",
        "run_tests",
        "test_outputs.py",
        "unittest",
        "validate",
        "validator",
    ]
    .iter()
    .any(|marker| lower.contains(marker))
}

fn validation_result_body_confirms_general_validator(body: &str) -> bool {
    let lower = body.to_ascii_lowercase();
    lower.contains("validator_tests_completed=true")
        || lower.contains("validator_lifecycle_stage=tests_completed")
        || lower.contains("pytest")
        || lower.contains("collected ")
        || lower.contains(" passed")
}

fn validation_output_contract_next_actions(
    changed_artifacts: &[String],
    requirements: &OutputContractValidationRequirements,
) -> Vec<String> {
    let mut actions = Vec::new();
    let script_command = changed_artifacts
        .iter()
        .find(|artifact| script_artifact_token(artifact))
        .map(|artifact| validation_changed_artifact_command(artifact));
    let contract_check = validation_output_contract_check_command(requirements);
    if let (Some(script_command), Some(contract_check)) = (&script_command, &contract_check) {
        actions.push(format!(
            "run_test with command `{script_command} && {contract_check}` to execute the changed artifact and validate declared output contract(s)"
        ));
    }
    if let Some(contract_check) = contract_check {
        actions.push(format!(
            "or run_test with command `{contract_check}` after the changed artifact has generated the declared output"
        ));
    }
    actions.push(
        "or run a real project/official validator command such as pytest, cargo test, npm test, or run-tests that validates the declared output contract(s)"
            .to_string(),
    );
    actions
}

fn validation_node_bootstrap_command(
    map: &ActionMapInstance,
    node: &MapNode,
    task: &TaskState,
) -> Option<String> {
    if !matches!(node.kind, NodeKind::SmokeTest | NodeKind::RegressionTest) {
        return None;
    }
    if node.result_context.iter().any(|result_ref| {
        map.results.get(&result_ref.id).is_some_and(|result| {
            matches!(
                result.action_class,
                Some(ActionClass::Build | ActionClass::Test)
            )
        })
    }) {
        return None;
    }
    if let Some(command) = discovered_required_local_validator_commands(map)
        .into_iter()
        .next()
    {
        return Some(command);
    }
    let changed_artifacts = validation_dependency_changed_artifacts(map, node);
    let requirements = task_output_contract_validation_requirements(task);
    let requirements =
        output_contract_requirements_for_validation_command(&requirements, &changed_artifacts);
    let script_command = changed_artifacts
        .iter()
        .find(|artifact| script_artifact_token(artifact))
        .map(|artifact| validation_changed_artifact_command(artifact));
    let contract_check = validation_output_contract_check_command(&requirements);
    match (script_command, contract_check) {
        (Some(script_command), Some(contract_check)) => {
            Some(format!("{script_command} && {contract_check}"))
        }
        (Some(script_command), None) => Some(script_command),
        (None, Some(contract_check)) => Some(contract_check),
        (None, None) => None,
    }
}

fn validation_output_contract_check_command(
    requirements: &OutputContractValidationRequirements,
) -> Option<String> {
    let output_target = requirements
        .targets
        .iter()
        .find(|target| {
            !requirements
                .schema_targets
                .iter()
                .any(|schema| artifact_refs_match(schema, target))
        })
        .or_else(|| requirements.targets.first())?;
    let local_output_target = local_workspace_command_artifact_ref(output_target);
    if let Some(schema_target) = requirements.schema_targets.first() {
        let local_schema_target = local_workspace_command_artifact_ref(schema_target);
        return Some(format!(
            "python -m jsonschema -i {local_output_target} {local_schema_target}"
        ));
    }
    if local_output_target.ends_with(".json") {
        return Some(format!(
            "python -c \"import json; data=json.load(open('{local_output_target}')); assert data\""
        ));
    }
    Some(format!("test -s {local_output_target}"))
}

fn summarize_artifact_refs(artifacts: &[String]) -> String {
    if artifacts.is_empty() {
        return "none recorded".to_string();
    }
    artifacts
        .iter()
        .take(4)
        .cloned()
        .collect::<Vec<_>>()
        .join(", ")
}

fn discovered_required_local_validator_commands(map: &ActionMapInstance) -> Vec<String> {
    let mut commands = Vec::new();
    for result in map.results.values() {
        let body = result.body.replace('\\', "/").to_ascii_lowercase();
        if body.contains("scripts/validate.py") {
            push_unique_string(&mut commands, "python scripts/validate.py".to_string());
        }
    }
    commands
}

fn command_covers_local_validator(command: &str, validator_command: &str) -> bool {
    let command = command.replace('\\', "/").to_ascii_lowercase();
    let validator_command = validator_command.replace('\\', "/").to_ascii_lowercase();
    command.contains(&validator_command)
        || command_mentions_artifact(&command, "scripts/validate.py")
        || command.contains(" scripts/validate.py")
}

fn artifact_refs_equivalent(left: &str, right: &str) -> bool {
    normalize_artifact_ref(left).eq_ignore_ascii_case(&normalize_artifact_ref(right))
}

fn push_unique_string(values: &mut Vec<String>, value: String) {
    if !values.iter().any(|existing| existing == &value) {
        values.push(value);
    }
}

fn validation_changed_artifact_action(artifact: &str) -> String {
    let normalized = normalize_artifact_ref(artifact);
    let command = validation_changed_artifact_command(&normalized);
    format!("run_test with command `{command}` to execute changed artifact `{normalized}`")
}

fn validation_changed_artifact_command(artifact: &str) -> String {
    let normalized = local_workspace_command_artifact_ref(artifact);
    if normalized.ends_with(".py") {
        format!("python {normalized}")
    } else if normalized.ends_with(".js") || normalized.ends_with(".mjs") {
        format!("node {normalized}")
    } else if normalized.ends_with(".sh") {
        format!("bash {normalized}")
    } else {
        normalized.clone()
    }
}

fn local_workspace_command_artifact_ref(artifact: &str) -> String {
    let normalized = normalize_artifact_ref(artifact);
    match normalized.as_str() {
        "/app" | "app" | "/app/src" | "app/src" => ".".to_string(),
        _ => normalized
            .strip_prefix("/app/src/")
            .or_else(|| normalized.strip_prefix("app/src/"))
            .or_else(|| normalized.strip_prefix("/app/"))
            .or_else(|| normalized.strip_prefix("app/"))
            .unwrap_or(&normalized)
            .to_string(),
    }
}

fn validation_node_failed_noninfra_result(
    map: &ActionMapInstance,
    node: &MapNode,
) -> Option<(String, String)> {
    node.result_context.iter().rev().find_map(|result_ref| {
        let result = map.results.get(&result_ref.id)?;
        if result.kind != NodeResultKind::MainToolCall
            || result.tool_success != Some(false)
            || !matches!(
                result.action_class,
                Some(ActionClass::Test | ActionClass::Build)
            )
            || is_local_validator_infra_failure(&result.body)
            || validation_failure_is_known_input_path_error(map, result)
            || validation_failure_is_missing_command_script_error(result)
            || validation_failure_is_missing_jsonschema_dependency(result)
        {
            return None;
        }
        Some((
            result.id.clone(),
            validation_failure_body_excerpt(&result.body, 640),
        ))
    })
}

fn validation_missing_jsonschema_dependency_next_actions(
    map: &ActionMapInstance,
    node: &MapNode,
    task: &TaskState,
) -> Vec<String> {
    let Some(result) = node.result_context.iter().rev().find_map(|result_ref| {
        let result = map.results.get(&result_ref.id)?;
        validation_failure_is_missing_jsonschema_dependency(result).then_some(result)
    }) else {
        return Vec::new();
    };
    let requirements = task_output_contract_validation_requirements(task);
    let changed_artifacts = validation_dependency_changed_artifacts(map, node);
    let requirements =
        output_contract_requirements_for_validation_command(&requirements, &changed_artifacts);
    let mut actions = validation_output_contract_check_command(&requirements)
        .map(|command| {
            vec![format!(
                "run_test with command `{command}` using the default python environment because `{}` failed to import jsonschema",
                result.id
            )]
        })
        .unwrap_or_default();
    actions.push(
        "do not route missing jsonschema module errors to implementation rework; run an available schema validator or block with exact validator dependency evidence"
            .to_string(),
    );
    actions
}

fn validation_failure_is_missing_jsonschema_dependency(result: &NodeResult) -> bool {
    if result.kind != NodeResultKind::MainToolCall
        || result.tool_success != Some(false)
        || !matches!(
            result.action_class,
            Some(ActionClass::Test | ActionClass::Build)
        )
    {
        return false;
    }
    let body = result.body.to_ascii_lowercase();
    body.contains("jsonschema")
        && body.contains("modulenotfounderror")
        && (body.contains("no module named 'jsonschema'")
            || body.contains("no module named \"jsonschema\""))
}

fn validation_failure_is_known_input_path_error(
    map: &ActionMapInstance,
    result: &NodeResult,
) -> bool {
    let body = result.body.replace('\\', "/").to_ascii_lowercase();
    if !body.contains("filenotfounderror") && !body.contains("no such file or directory") {
        return false;
    }
    let command_section = body
        .split("raw_output:")
        .next()
        .unwrap_or(body.as_str())
        .to_string();
    let known_artifacts = map
        .results
        .values()
        .flat_map(result_visible_artifact_refs)
        .collect::<Vec<_>>();
    known_artifacts.iter().any(|artifact| {
        let normalized = normalize_artifact_ref(artifact).to_ascii_lowercase();
        let Some(file_name) = normalized.rsplit('/').next() else {
            return false;
        };
        !file_name.is_empty()
            && normalized.contains('/')
            && command_section.contains(file_name)
            && !command_section.contains(&normalized)
    })
}

fn validation_failure_is_missing_command_script_error(result: &NodeResult) -> bool {
    let body = result.body.replace('\\', "/").to_ascii_lowercase();
    if !body.contains("can't open file") && !body.contains("cannot open file") {
        return false;
    }
    let Some(script_ref) = missing_command_script_ref(&body) else {
        return false;
    };
    script_artifact_token(&script_ref)
}

fn missing_command_script_ref(body: &str) -> Option<String> {
    let marker = if body.contains("can't open file") {
        "can't open file"
    } else {
        "cannot open file"
    };
    let (_, rest) = body.split_once(marker)?;
    let rest = rest.trim_start_matches(|ch: char| ch.is_whitespace() || ch == ':');
    if let Some(rest) = rest.strip_prefix('\'') {
        return rest.split_once('\'').map(|(path, _)| path.to_string());
    }
    if let Some(rest) = rest.strip_prefix('"') {
        return rest.split_once('"').map(|(path, _)| path.to_string());
    }
    rest.split(|ch: char| ch.is_whitespace() || ch == ':')
        .next()
        .map(str::to_string)
}

fn validation_node_semantic_failure_result(
    map: &ActionMapInstance,
    node: &MapNode,
) -> Option<(String, String)> {
    node.result_context.iter().rev().find_map(|result_ref| {
        let result = map.results.get(&result_ref.id)?;
        if result.kind != NodeResultKind::MainToolCall
            || result.tool_success != Some(true)
            || !matches!(
                result.action_class,
                Some(ActionClass::Test | ActionClass::Build)
            )
            || node_result_is_successful_validation(result)
            || !validation_output_indicates_failure(&result.body)
        {
            return None;
        }
        Some((
            result.id.clone(),
            validation_failure_body_excerpt(&result.body, 640),
        ))
    })
}

fn validation_node_local_infra_unvalidated_artifact_result(
    map: &ActionMapInstance,
    node: &MapNode,
) -> Option<(String, String)> {
    if node_has_successful_validation_action(map, node) {
        return None;
    }
    let changed_artifacts = validation_dependency_changed_artifacts(map, node);
    if changed_artifacts.is_empty() {
        return None;
    }
    node.result_context.iter().rev().find_map(|result_ref| {
        let result = map.results.get(&result_ref.id)?;
        if !node_result_is_local_validator_infra_failure(result)
            || !local_validator_infra_failure_can_rework_command(&result.body)
        {
            return None;
        }
        Some((
            result.id.clone(),
            format!(
                "local validator infrastructure failed before changed artifacts were proven. Changed artifacts still need platform-compatible execution: {}.{} Failure preview: {}",
                changed_artifacts.join(", "),
                platform_compatible_validation_command_hint(&changed_artifacts),
                single_line_preview(&result.body, 180)
            ),
        ))
    })
}

fn validation_node_local_infra_blocker_unvalidated_artifact_result(
    map: &ActionMapInstance,
    node: &MapNode,
    blocker_summary: &str,
) -> Option<(String, String)> {
    if node_has_successful_validation_action(map, node)
        || !text_mentions_local_validator_infra_failure(blocker_summary)
        || !local_validator_infra_failure_can_rework_command(blocker_summary)
    {
        return None;
    }
    let changed_artifacts = validation_dependency_changed_artifacts(map, node);
    if changed_artifacts.is_empty() {
        return None;
    }
    Some((
        "blocked_validation_local_infra".to_string(),
        format!(
            "local validator infrastructure blocker was recorded before changed artifacts were proven. Changed artifacts still need platform-compatible execution: {}.{} Blocker preview: {}",
            changed_artifacts.join(", "),
            platform_compatible_validation_command_hint(&changed_artifacts),
            single_line_preview(blocker_summary, 180)
        ),
    ))
}

fn unresolved_validation_rework_requirement(
    map: &ActionMapInstance,
) -> Option<(String, String, String)> {
    let mut node_ids = map.nodes.keys().cloned().collect::<Vec<_>>();
    node_ids.sort();
    node_ids.into_iter().find_map(|node_id| {
        let node = map.nodes.get(&node_id)?;
        if !matches!(node.kind, NodeKind::SmokeTest | NodeKind::RegressionTest)
            || matches!(node.status, NodeStatus::Blocked | NodeStatus::Completed)
        {
            return None;
        }
        validation_node_failed_noninfra_result(map, node)
            .or_else(|| validation_node_local_infra_unvalidated_artifact_result(map, node))
            .map(|(result_id, summary)| (node_id, result_id, summary))
    })
}

fn tool_action_descriptor_command(descriptor: &ToolActionDescriptor) -> Option<String> {
    serde_json::from_str::<serde_json::Value>(&descriptor.preview)
        .ok()
        .and_then(|value| {
            value
                .get("command")
                .and_then(serde_json::Value::as_str)
                .map(str::to_string)
        })
        .or_else(|| {
            let preview = descriptor.preview.trim();
            (!preview.is_empty()).then(|| preview.to_string())
        })
}

fn tool_action_descriptor_targets_any_artifact(
    descriptor: &ToolActionDescriptor,
    artifact_refs: &[String],
) -> bool {
    tool_action_descriptor_matching_artifact_ref(descriptor, artifact_refs).is_some()
}

fn tool_action_descriptor_matching_artifact_ref(
    descriptor: &ToolActionDescriptor,
    artifact_refs: &[String],
) -> Option<String> {
    let Some(command) = tool_action_descriptor_command(descriptor) else {
        return None;
    };
    let normalized_command = normalize_artifact_ref(&command).to_ascii_lowercase();
    artifact_refs.iter().find_map(|artifact_ref| {
        let key = artifact_key(artifact_ref);
        (!key.is_empty() && normalized_command.contains(&key)).then(|| artifact_ref.clone())
    })
}

fn inspect_duplicate_successful_diagnostic_test(
    map: &ActionMapInstance,
    node: &MapNode,
    descriptor: &ToolActionDescriptor,
) -> Option<(NodeResultId, String)> {
    let command = tool_action_descriptor_command(descriptor)?;
    let normalized_command = normalize_command_for_repeat_detection(&command);
    if normalized_command.is_empty() {
        return None;
    }
    node.result_context.iter().rev().find_map(|result_ref| {
        let result = map.results.get(&result_ref.id)?;
        if result.kind != NodeResultKind::MainToolCall
            || result.tool_success != Some(true)
            || !matches!(
                result.action_class,
                Some(ActionClass::Test | ActionClass::Build)
            )
        {
            return None;
        }
        let previous_command = result_body_command(result)
            .map(|command| normalize_command_for_repeat_detection(&command))
            .unwrap_or_default();
        if previous_command == normalized_command {
            Some((result.id.clone(), command.clone()))
        } else {
            None
        }
    })
}

fn inspect_duplicate_successful_read_or_search(
    map: &ActionMapInstance,
    node: &MapNode,
    descriptor: &ToolActionDescriptor,
) -> Option<(NodeResultId, String)> {
    let command = tool_action_descriptor_command(descriptor)?;
    let normalized_command = normalize_command_for_repeat_detection(&command);
    if normalized_command.is_empty() {
        return None;
    }
    node.result_context.iter().rev().find_map(|result_ref| {
        let result = map.results.get(&result_ref.id)?;
        if result.kind != NodeResultKind::MainToolCall
            || result.tool_success != Some(true)
            || !matches!(
                result.action_class,
                Some(ActionClass::Read | ActionClass::Search)
            )
        {
            return None;
        }
        let previous_command = result_body_command(result)
            .map(|command| normalize_command_for_repeat_detection(&command))
            .unwrap_or_default();
        if previous_command == normalized_command {
            Some((result.id.clone(), command.clone()))
        } else {
            None
        }
    })
}

fn result_body_command(result: &NodeResult) -> Option<String> {
    result
        .body
        .lines()
        .find_map(|line| line.strip_prefix("command: ").map(str::trim))
        .map(str::to_string)
}

fn normalize_command_for_repeat_detection(command: &str) -> String {
    command
        .split_whitespace()
        .collect::<Vec<_>>()
        .join(" ")
        .to_ascii_lowercase()
}

fn latest_gate_recovery_key(map_id: &str, node_id: &str) -> String {
    format!("{map_id}\x1f{node_id}")
}

fn command_is_general_validation_runner(command: &str) -> bool {
    let lower = command.to_ascii_lowercase();
    [
        "pytest",
        "cargo test",
        "npm test",
        "pnpm test",
        "yarn test",
        "go test",
        "mvn test",
        "gradle test",
        "run-tests",
        "run_tests",
        "run_pipeline",
        "scripts/validate.py",
        "test_outputs.py",
    ]
    .iter()
    .any(|marker| lower.contains(marker))
}

fn command_invokes_script_artifact(command: &str) -> bool {
    let normalized = command.replace('\\', "/").to_ascii_lowercase();
    for marker in ["python ", "python3 ", "py ", "node ", "bash ", "sh "] {
        let mut rest = normalized.as_str();
        while let Some((_, after_marker)) = rest.split_once(marker) {
            let token = after_marker
                .trim_start()
                .split(|ch: char| ch.is_whitespace() || matches!(ch, '&' | '|' | ';' | ')' | '('))
                .next()
                .unwrap_or("")
                .trim_matches(|ch| matches!(ch, '"' | '\'' | '`'));
            if !token.starts_with('-') && script_artifact_token(token) {
                return true;
            }
            rest = after_marker;
        }
    }
    false
}

fn script_artifact_token(token: &str) -> bool {
    let normalized =
        normalize_artifact_ref(token.trim_matches(|ch| matches!(ch, '"' | '\'' | '`')));
    matches!(
        normalized.rsplit_once('.').map(|(_, ext)| ext),
        Some("py" | "js" | "mjs" | "sh")
    )
}

fn shell_single_quote_arg(value: &str) -> String {
    if value
        .chars()
        .all(|ch| ch.is_ascii_alphanumeric() || matches!(ch, '.' | '/' | '_' | '-'))
    {
        return value.to_string();
    }
    format!("'{}'", value.replace('\'', "'\\''"))
}

fn platform_compatible_validation_commands(artifacts: &[String]) -> Vec<String> {
    artifacts
        .iter()
        .filter_map(|artifact| {
            let normalized = normalize_artifact_ref(artifact);
            let quoted = shell_single_quote_arg(&normalized);
            match normalized.rsplit_once('.').map(|(_, ext)| ext) {
                Some("py") => Some(format!("python {quoted}")),
                Some("js" | "mjs") => Some(format!("node {quoted}")),
                Some("sh") => Some(format!("sh {quoted}")),
                _ => None,
            }
        })
        .collect()
}

fn platform_compatible_validation_command_hint(artifacts: &[String]) -> String {
    let commands = platform_compatible_validation_commands(artifacts);
    if commands.is_empty() {
        return String::new();
    }
    format!(
        " Suggested platform-compatible command(s): {}.",
        commands
            .iter()
            .map(|command| format!("`{command}`"))
            .collect::<Vec<_>>()
            .join(", ")
    )
}

fn validation_dependency_changed_artifacts(map: &ActionMapInstance, node: &MapNode) -> Vec<String> {
    let dependency_ids = map
        .edges
        .iter()
        .filter(|edge| edge.to == node.id)
        .map(|edge| edge.from.as_str())
        .collect::<Vec<_>>();
    let mut artifacts = Vec::new();
    for dependency_id in dependency_ids {
        let Some(dependency) = map.nodes.get(dependency_id) else {
            continue;
        };
        if dependency.kind != NodeKind::ImplementSolution {
            continue;
        }
        for result_ref in &dependency.result_context {
            let Some(result) = map.results.get(&result_ref.id) else {
                continue;
            };
            if result.kind != NodeResultKind::MainToolCall
                || result.tool_success != Some(true)
                || result.action_class != Some(ActionClass::Edit)
            {
                continue;
            }
            for artifact in result_artifact_refs(result) {
                if !artifacts.iter().any(|existing| existing == &artifact) {
                    artifacts.push(artifact);
                }
            }
        }
    }
    artifacts
}

fn task_output_contract_artifact_targets(task: &TaskState) -> Vec<String> {
    let mut targets = Vec::new();
    for contract in &task.cognitive_state.output_contracts {
        let schema_or_validator_contract = matches!(
            contract.kind,
            OutputContractKind::Schema | OutputContractKind::Validator
        );
        for value in [&contract.id, &contract.description] {
            for artifact in extract_artifact_like_refs(value) {
                if schema_or_validator_contract
                    || output_contract_artifact_ref_looks_like_schema_or_validator(&artifact)
                {
                    continue;
                }
                if !targets.iter().any(|existing| existing == &artifact) {
                    targets.push(artifact);
                }
            }
        }
        for evidence in &contract.evidence_refs {
            if let Some(artifact) = evidence.artifact_ref.as_deref() {
                let artifact = normalize_artifact_ref(artifact);
                if schema_or_validator_contract
                    || output_contract_artifact_ref_looks_like_schema_or_validator(&artifact)
                {
                    continue;
                }
                if !targets.iter().any(|existing| existing == &artifact) {
                    targets.push(artifact);
                }
            }
        }
    }
    targets
}

fn task_required_fact_source_artifact_refs(task: &TaskState) -> Vec<String> {
    let mut artifact_refs = Vec::new();
    let output_targets = task_output_contract_artifact_targets(task);
    for source in &task.cognitive_state.fact_sources {
        if fact_source_is_optional(source) {
            continue;
        }
        for value in [&source.id, &source.description] {
            for artifact in extract_artifact_like_refs(value) {
                push_requirement_fact_source_artifact_ref(
                    &mut artifact_refs,
                    artifact,
                    &output_targets,
                );
            }
        }
        for evidence in &source.evidence_refs {
            if let Some(artifact_ref) = evidence.artifact_ref.as_deref() {
                push_requirement_fact_source_artifact_ref(
                    &mut artifact_refs,
                    normalize_artifact_ref(artifact_ref),
                    &output_targets,
                );
            }
        }
    }
    for criterion in &task.problem_ledger.success_criteria {
        push_requirement_text_fact_source_artifact_refs(
            &mut artifact_refs,
            &criterion.description,
            &output_targets,
        );
        for evidence in &criterion.evidence_refs {
            if let Some(artifact_ref) = evidence.artifact_ref.as_deref() {
                push_requirement_fact_source_artifact_ref(
                    &mut artifact_refs,
                    normalize_artifact_ref(artifact_ref),
                    &output_targets,
                );
            }
        }
    }
    for criterion in &task.cognitive_state.success_criteria {
        push_requirement_text_fact_source_artifact_refs(
            &mut artifact_refs,
            criterion,
            &output_targets,
        );
    }
    artifact_refs
}

fn push_requirement_text_fact_source_artifact_refs(
    artifact_refs: &mut Vec<String>,
    text: &str,
    output_targets: &[String],
) {
    if fact_source_text_is_optional(text) {
        return;
    }
    for artifact in extract_artifact_like_refs(text) {
        push_requirement_fact_source_artifact_ref(artifact_refs, artifact, output_targets);
    }
}

fn push_requirement_fact_source_artifact_ref(
    artifact_refs: &mut Vec<String>,
    artifact_ref: String,
    output_targets: &[String],
) {
    let artifact_ref = normalize_artifact_ref(&artifact_ref);
    if output_targets
        .iter()
        .any(|target| artifact_refs_match(target, &artifact_ref))
        || output_contract_artifact_ref_looks_like_generated_json_output(&artifact_ref)
    {
        return;
    }
    push_required_fact_source_artifact_ref(artifact_refs, artifact_ref);
}

fn fact_source_is_optional(source: &FactSource) -> bool {
    fact_source_text_is_optional(&source.id) || fact_source_text_is_optional(&source.description)
}

fn fact_source_text_is_optional(text: &str) -> bool {
    let lower = text.to_ascii_lowercase();
    [
        "if present",
        "if available",
        "if any",
        "if provided",
        "if supplied",
        "if it exists",
        "if they exist",
        "when present",
        "when available",
        "where present",
        "where available",
        "as available",
        "optional",
        "optionally",
    ]
    .iter()
    .any(|marker| lower.contains(marker))
}

fn push_required_fact_source_artifact_ref(artifact_refs: &mut Vec<String>, artifact_ref: String) {
    if !required_fact_source_artifact_ref(&artifact_ref)
        || artifact_refs
            .iter()
            .any(|existing| artifact_refs_match(existing, &artifact_ref))
    {
        return;
    }
    artifact_refs.push(artifact_ref);
}

fn required_fact_source_artifact_ref(artifact_ref: &str) -> bool {
    let normalized = normalize_artifact_ref(artifact_ref);
    let lower = normalized.to_ascii_lowercase();
    if lower.is_empty()
        || lower.contains("://")
        || lower.starts_with("test-fixture:")
        || lower.starts_with("output-ref:")
        || lower.starts_with("validator:")
    {
        return false;
    }
    artifact_like_token(&normalized)
}

fn inspect_missing_required_fact_source_artifacts(
    task: &TaskState,
    map: &ActionMapInstance,
    node: &MapNode,
) -> Vec<String> {
    let required = inspect_required_fact_source_artifacts(task, map, node);
    inspect_missing_required_fact_source_artifacts_from_required(&required, map, node)
}

fn inspect_required_fact_source_artifacts(
    task: &TaskState,
    map: &ActionMapInstance,
    node: &MapNode,
) -> Vec<String> {
    let mut required = task_required_fact_source_artifact_refs(task);
    for artifact in inspect_node_discovered_required_input_artifact_refs(task, map, node) {
        push_required_fact_source_artifact_ref(&mut required, artifact);
    }
    required
}

fn inspect_missing_required_fact_source_artifacts_from_required(
    required: &[String],
    map: &ActionMapInstance,
    node: &MapNode,
) -> Vec<String> {
    let observed_artifacts = inspect_node_observed_artifact_refs(map, node);
    required
        .iter()
        .filter(|required| {
            !observed_artifacts
                .iter()
                .any(|observed| artifact_refs_match(required, observed))
        })
        .cloned()
        .collect()
}

fn inspect_node_discovered_required_input_artifact_refs(
    task: &TaskState,
    map: &ActionMapInstance,
    node: &MapNode,
) -> Vec<String> {
    let extensions = task_required_generic_input_extensions(task);
    if extensions.is_empty() {
        return Vec::new();
    }
    let mut artifacts: Vec<String> = Vec::new();
    for result_ref in &node.result_context {
        let Some(result) = map.results.get(&result_ref.id) else {
            continue;
        };
        if result.kind != NodeResultKind::MainToolCall
            || result.tool_success != Some(true)
            || !matches!(
                result.action_class,
                Some(ActionClass::Read | ActionClass::Search)
            )
        {
            continue;
        }
        for artifact in extract_artifact_like_refs(&result.body) {
            if !artifact.contains('*')
                && !artifact.contains('?')
                && artifact_has_any_extension(&artifact, &extensions)
                && !artifacts
                    .iter()
                    .any(|existing| artifact_refs_match(existing, &artifact))
            {
                artifacts.push(artifact);
            }
        }
    }
    canonicalize_discovered_required_input_artifacts(artifacts)
}

fn task_required_generic_input_extensions(task: &TaskState) -> Vec<&'static str> {
    let mut extensions = Vec::new();
    for text in task_requirement_texts(task) {
        let lower = text.to_ascii_lowercase();
        if (lower.contains("csv files")
            || lower.contains("csv file")
            || lower.contains("csv data")
            || lower.contains("csv input")
            || lower.contains("csv source"))
            && !extensions.contains(&"csv")
        {
            extensions.push("csv");
        }
    }
    extensions
}

fn task_requirement_texts(task: &TaskState) -> Vec<&str> {
    let mut texts = vec![task.title.as_str(), task.objective.as_str()];
    for source in &task.cognitive_state.fact_sources {
        texts.push(source.id.as_str());
        texts.push(source.description.as_str());
    }
    for criterion in &task.problem_ledger.success_criteria {
        texts.push(criterion.description.as_str());
    }
    for criterion in &task.cognitive_state.success_criteria {
        texts.push(criterion.as_str());
    }
    texts
}

fn canonicalize_discovered_required_input_artifacts(artifacts: Vec<String>) -> Vec<String> {
    let mut canonical: Vec<String> = Vec::new();
    for artifact in artifacts {
        let key = artifact_file_key(&artifact);
        if let Some(existing_index) = canonical
            .iter()
            .position(|existing| artifact_file_key(existing) == key)
        {
            if discovered_input_artifact_preferred(&artifact, &canonical[existing_index]) {
                canonical[existing_index] = artifact;
            }
        } else {
            canonical.push(artifact);
        }
    }
    canonical
}

fn discovered_input_artifact_preferred(candidate: &str, current: &str) -> bool {
    let candidate = normalize_artifact_ref(candidate);
    let current = normalize_artifact_ref(current);
    let candidate_depth = candidate.matches('/').count();
    let current_depth = current.matches('/').count();
    candidate_depth < current_depth
        || (candidate_depth == current_depth && candidate.len() < current.len())
}

fn artifact_has_any_extension(artifact: &str, extensions: &[&str]) -> bool {
    let lower = normalize_artifact_ref(artifact).to_ascii_lowercase();
    lower
        .rsplit_once('.')
        .is_some_and(|(_, ext)| extensions.iter().any(|expected| ext == *expected))
}

fn observed_required_fact_source_artifacts(
    task: &TaskState,
    map: &ActionMapInstance,
) -> Vec<String> {
    let required = task_required_fact_source_artifact_refs(task);
    if required.is_empty() {
        return Vec::new();
    }
    let mut observed = Vec::new();
    for node in map.nodes.values() {
        if node.kind != NodeKind::InspectCodeContext {
            continue;
        }
        for artifact in inspect_node_observed_artifact_refs(map, node) {
            if required
                .iter()
                .any(|required| artifact_refs_match(required, &artifact))
            {
                push_unique_artifact_ref(&mut observed, artifact);
            }
        }
    }
    observed
}

fn inspect_node_observed_artifact_refs(map: &ActionMapInstance, node: &MapNode) -> Vec<String> {
    let mut artifact_refs = Vec::new();
    for result_ref in &node.result_context {
        let Some(result) = map.results.get(&result_ref.id) else {
            continue;
        };
        if result.kind != NodeResultKind::MainToolCall
            || result.tool_success != Some(true)
            || !matches!(
                result.action_class,
                Some(ActionClass::Read | ActionClass::Search)
            )
        {
            continue;
        }
        for artifact in result_visible_artifact_refs(result) {
            push_unique_artifact_ref(&mut artifact_refs, artifact);
        }
        for artifact in result_input_data_artifact_refs(result) {
            push_unique_artifact_ref(&mut artifact_refs, artifact);
        }
        if let Some(command) = result_body_command(result) {
            for artifact in command_artifact_refs(&command) {
                push_unique_artifact_ref(&mut artifact_refs, artifact);
            }
        }
    }
    artifact_refs
}

fn command_artifact_refs(command: &str) -> Vec<String> {
    let mut artifact_refs = Vec::new();
    for artifact in extract_artifact_like_refs(command) {
        let normalized = normalize_artifact_ref(&artifact);
        if normalized.starts_with('-') || normalized.contains('*') || normalized.contains('?') {
            continue;
        }
        push_unique_artifact_ref(&mut artifact_refs, normalized);
    }
    artifact_refs
}

fn push_unique_artifact_ref(artifact_refs: &mut Vec<String>, artifact_ref: String) {
    if !artifact_ref.is_empty()
        && !artifact_refs
            .iter()
            .any(|existing| artifact_refs_match(existing, &artifact_ref))
    {
        artifact_refs.push(artifact_ref);
    }
}

fn artifact_refs_match(left: &str, right: &str) -> bool {
    if artifact_refs_equivalent(left, right) {
        return true;
    }
    let left_variants = artifact_command_match_variants(left);
    let right_variants = artifact_command_match_variants(right);
    left_variants
        .iter()
        .any(|left| right_variants.iter().any(|right| left == right))
}

fn command_mentions_artifact(command: &str, artifact: &str) -> bool {
    let command = command.replace('\\', "/").to_ascii_lowercase();
    artifact_command_match_variants(artifact)
        .into_iter()
        .any(|variant| !variant.is_empty() && command.contains(&variant))
}

fn artifact_command_match_variants(artifact: &str) -> Vec<String> {
    let normalized = normalize_artifact_ref(artifact).to_ascii_lowercase();
    let mut variants = vec![normalized.clone()];
    for marker in ["/app/src/", "/app/", "app/src/", "app/"] {
        if let Some((_, suffix)) = normalized.split_once(marker) {
            variants.push(suffix.trim_matches('/').to_string());
        }
    }
    if let Some(file_name) = normalized.rsplit('/').next()
        && file_name.len() >= 4
    {
        variants.push(file_name.to_string());
    }
    variants.sort();
    variants.dedup();
    variants
}

fn extract_artifact_like_refs(text: &str) -> Vec<String> {
    text.split(|ch: char| {
        ch.is_whitespace()
            || matches!(
                ch,
                '"' | '\'' | '`' | ',' | ';' | ':' | '(' | ')' | '[' | ']' | '{' | '}' | '<' | '>'
            )
    })
    .map(|token| token.trim_matches(|ch: char| matches!(ch, '.' | '!' | '?' | '#')))
    .filter(|token| artifact_like_token(token))
    .map(normalize_artifact_ref)
    .collect()
}

fn artifact_like_token(token: &str) -> bool {
    let token = token.trim();
    if token.is_empty() {
        return false;
    }
    let lower = token.to_ascii_lowercase();
    if matches!(
        lower.rsplit_once('.').map(|(_, ext)| ext),
        Some(
            "py" | "js"
                | "ts"
                | "rs"
                | "sh"
                | "json"
                | "jsonl"
                | "csv"
                | "tsv"
                | "txt"
                | "md"
                | "yaml"
                | "yml"
                | "toml"
        )
    ) {
        return true;
    }
    slash_artifact_like_token(&lower)
}

fn slash_artifact_like_token(token: &str) -> bool {
    let normalized = token.replace('\\', "/");
    if !normalized.contains('/') {
        return false;
    }
    if normalized.ends_with('/')
        || normalized.starts_with("./")
        || normalized.starts_with("../")
        || normalized.starts_with('/')
        || normalized.starts_with("~/")
    {
        return true;
    }
    [
        "src/",
        "tests/",
        "test/",
        "data/",
        "scripts/",
        "script/",
        "docs/",
        "doc/",
        "config/",
        "configs/",
        ".github/",
        "third_party/",
        "examples/",
        "fixtures/",
        "fixture/",
        "benchmarks/",
    ]
    .iter()
    .any(|marker| normalized.starts_with(marker) || normalized.contains(&format!("/{marker}")))
}

fn read_command_artifact_ref(command: &str) -> Option<String> {
    if command.contains("Get-Content") {
        return powershell_path_arg(command)
            .as_deref()
            .map(normalize_artifact_ref);
    }
    if let Some(path) = sed_read_command_artifact_ref(command) {
        return Some(path);
    }
    command
        .strip_prefix("cat ")
        .or_else(|| command.strip_prefix("type "))
        .map(str::trim)
        .map(|path| normalize_artifact_ref(path.trim_matches('"').trim_matches('\'')))
}

fn sed_read_command_artifact_ref(command: &str) -> Option<String> {
    let tokens = shlex::split(command)?;
    if tokens.first().map(String::as_str) != Some("sed") {
        return None;
    }

    let mut paths = Vec::new();
    let mut tokens = tokens.iter().skip(1).peekable();
    let mut after_double_dash = false;
    while let Some(token) = tokens.next() {
        if matches!(token.as_str(), "&&" | ";" | "||") {
            break;
        }
        if after_double_dash {
            paths.push(token.as_str());
            continue;
        }
        if token == "--" {
            after_double_dash = true;
            continue;
        }
        if token == "-n" {
            let _ = tokens.next();
            continue;
        }
        if token.starts_with("-n") {
            continue;
        }
        if token.starts_with('-') {
            continue;
        }
        paths.push(token.as_str());
    }

    (paths.len() == 1).then(|| normalize_artifact_ref(paths[0]))
}

fn powershell_path_arg(command: &str) -> Option<String> {
    let marker = if command.contains("-LiteralPath") {
        "-LiteralPath"
    } else if command.contains("-Path") {
        "-Path"
    } else {
        return None;
    };
    let start = command.find(marker)? + marker.len();
    let rest = command[start..].trim_start();
    if let Some(rest) = rest.strip_prefix('"') {
        let end = rest.find('"')?;
        return Some(rest[..end].to_string());
    }
    let end = rest.find(char::is_whitespace).unwrap_or(rest.len());
    Some(rest[..end].to_string())
}

fn extract_edit_changed_artifacts_from_tool_body(body: &str) -> Vec<String> {
    let mut artifacts = Vec::new();
    let normalized_body = body.replace("\\n", "\n");
    for line in normalized_body.lines() {
        let trimmed = line.trim();
        let Some(path) = trimmed
            .strip_prefix("M ")
            .or_else(|| trimmed.strip_prefix("A "))
            .or_else(|| trimmed.strip_prefix("D "))
            .or_else(|| trimmed.strip_prefix("*** Update File: "))
            .or_else(|| trimmed.strip_prefix("*** Add File: "))
            .or_else(|| trimmed.strip_prefix("+++ b/"))
            .or_else(|| trimmed.strip_prefix("+++ "))
        else {
            continue;
        };
        let path = path.trim();
        if path.is_empty()
            || path.starts_with("user-request")
            || path.starts_with("output-ref://")
            || path == "/dev/null"
            || path.contains('\0')
        {
            continue;
        }
        let path = normalize_artifact_ref(path);
        if !artifacts.iter().any(|existing| existing == &path) {
            artifacts.push(path);
        }
    }
    artifacts
}

fn normalize_artifact_ref(path: &str) -> String {
    path.trim()
        .strip_prefix("path=")
        .unwrap_or(path.trim())
        .trim_start_matches("a/")
        .trim_start_matches("b/")
        .trim_start_matches("./")
        .replace('\\', "/")
}

fn validation_failure_text_artifact_refs(text: &str) -> Vec<String> {
    let mut artifacts = Vec::new();
    for raw_token in text.split(|ch: char| ch.is_whitespace() || matches!(ch, '"' | '\'' | '`')) {
        let token = raw_token.trim_matches(|ch: char| {
            matches!(
                ch,
                ',' | ':' | ';' | ')' | '(' | '[' | ']' | '{' | '}' | '<' | '>'
            )
        });
        let lower = token.to_ascii_lowercase();
        if !is_validation_failure_artifact_token(&lower) {
            continue;
        }
        let artifact_ref = normalize_failure_artifact_token(token);
        if !validation_failure_artifact_ref_is_rework_target(&artifact_ref) {
            continue;
        }
        if !artifact_ref.is_empty() && !artifacts.iter().any(|existing| existing == &artifact_ref) {
            artifacts.push(artifact_ref);
        }
    }
    artifacts
}

fn is_validation_failure_artifact_token(lower: &str) -> bool {
    [
        ".py", ".rs", ".js", ".ts", ".tsx", ".jsx", ".sh", ".ps1", ".go", ".java", ".c", ".cpp",
        ".h", ".hpp",
    ]
    .iter()
    .any(|suffix| lower.ends_with(suffix) || lower.contains(&format!("{suffix}:")))
}

fn validation_failure_artifact_ref_is_rework_target(artifact_ref: &str) -> bool {
    let normalized = normalize_artifact_ref(artifact_ref);
    let lower = normalized.to_ascii_lowercase();
    if lower.is_empty()
        || lower.contains("/site-packages/")
        || lower.contains("/dist-packages/")
        || lower.contains("/lib/python")
        || lower.contains("/miniconda")
        || lower.contains("/jsonschema/")
        || lower.contains("/python3.")
    {
        return false;
    }
    if lower.starts_with('/') || lower.starts_with("~/") {
        return false;
    }
    true
}

fn normalize_failure_artifact_token(token: &str) -> String {
    let mut normalized = normalize_artifact_ref(token);
    while let Some(idx) = normalized.find("/app/") {
        normalized = normalized[idx + "/app/".len()..].to_string();
    }
    if normalized.len() > 2 && normalized.as_bytes().get(1) == Some(&b':') {
        normalized = normalized[2..].trim_start_matches('/').to_string();
    }
    normalized
        .trim_matches(|ch: char| {
            matches!(
                ch,
                ',' | ':' | ';' | ')' | '(' | '[' | ']' | '{' | '}' | '<' | '>'
            )
        })
        .to_string()
}

fn is_implementation_surface_ref(artifact_ref: &str) -> bool {
    let normalized = artifact_ref.replace('\\', "/").to_ascii_lowercase();
    if normalized == "readme.md" || normalized.starts_with("docs/") {
        return false;
    }
    if normalized.starts_with("tests/") || normalized.contains("/tests/") {
        return false;
    }
    normalized.contains('/')
}

fn related_completed_accepted_subagent_inspect_node_ids(
    map: &ActionMapInstance,
    owner_session_id: ThreadId,
    ancestor_node_ids: &[String],
) -> Vec<String> {
    let mut node_ids = completed_subagent_inspect_node_ids(map, owner_session_id)
        .into_iter()
        .filter(|node_id| node_depends_on_any(map, node_id, ancestor_node_ids))
        .collect::<Vec<_>>();
    node_ids.sort();
    node_ids
}

fn node_depends_on_any(
    map: &ActionMapInstance,
    node_id: &str,
    ancestor_node_ids: &[String],
) -> bool {
    let ancestors = ancestor_node_ids
        .iter()
        .map(String::as_str)
        .collect::<HashSet<_>>();
    let mut stack = map
        .edges
        .iter()
        .filter(|edge| edge.to == node_id)
        .map(|edge| edge.from.as_str())
        .collect::<Vec<_>>();
    let mut seen = HashSet::new();
    while let Some(current) = stack.pop() {
        if !seen.insert(current) {
            continue;
        }
        if ancestors.contains(current) {
            return true;
        }
        for edge in map.edges.iter().filter(|edge| edge.to == current) {
            stack.push(edge.from.as_str());
        }
    }
    false
}

