fn implement_node_dependency_validation_rework_schema_item_type_mismatches(
    map: &ActionMapInstance,
    node: &MapNode,
) -> Vec<String> {
    let mut expected_types = HashSet::new();
    for dependency_node_id in implement_node_validation_rework_dependency_node_ids(map, node) {
        let Some(dependency) = map.nodes.get(&dependency_node_id) else {
            continue;
        };
        if !matches!(
            dependency.kind,
            NodeKind::SmokeTest | NodeKind::RegressionTest
        ) || dependency.status != NodeStatus::Blocked
        {
            continue;
        }
        for result_ref in &dependency.result_context {
            let Some(result) = map.results.get(&result_ref.id) else {
                continue;
            };
            if result.kind != NodeResultKind::MainToolCall && result.kind != NodeResultKind::Blocker
            {
                continue;
            }
            for expected_type in validation_failure_unlocated_expected_types(&result.body) {
                expected_types.insert(expected_type);
            }
        }
    }
    if expected_types.is_empty() {
        return Vec::new();
    }

    let mut mismatches = Vec::new();
    let mut seen = HashSet::new();
    for dependency_node_id in implement_node_transitive_dependency_node_ids(map, node) {
        let Some(dependency) = map.nodes.get(&dependency_node_id) else {
            continue;
        };
        for result_ref in &dependency.result_context {
            let Some(result) = map.results.get(&result_ref.id) else {
                continue;
            };
            if result.kind != NodeResultKind::MainToolCall
                || result.tool_success != Some(true)
                || !matches!(
                    result.action_class,
                    Some(ActionClass::Read | ActionClass::Search)
                )
            {
                continue;
            }
            for expectation in schema_array_item_type_expectations_from_tool_result(result) {
                if !expected_types.contains(&expectation.expected_item_type) {
                    continue;
                }
                let key = format!(
                    "{}:{}:{}:{}",
                    expectation.source_artifact,
                    expectation.path,
                    expectation.property,
                    expectation.expected_item_type
                );
                if seen.insert(key) {
                    mismatches.push(format!(
                        "{} expected {} items",
                        expectation.property, expectation.expected_item_type
                    ));
                }
                if mismatches.len() >= 6 {
                    return mismatches;
                }
            }
        }
    }
    mismatches
}

fn implement_node_dependency_validation_rework_property_rename_hints(
    map: &ActionMapInstance,
    node: &MapNode,
    missing_required_properties: &[String],
) -> Vec<String> {
    if missing_required_properties.is_empty() {
        return Vec::new();
    }
    let mut hints = Vec::new();
    for dependency_node_id in implement_node_validation_rework_dependency_node_ids(map, node) {
        let Some(dependency) = map.nodes.get(&dependency_node_id) else {
            continue;
        };
        if !matches!(
            dependency.kind,
            NodeKind::SmokeTest | NodeKind::RegressionTest
        ) || dependency.status != NodeStatus::Blocked
        {
            continue;
        }
        for result_ref in &dependency.result_context {
            let Some(result) = map.results.get(&result_ref.id) else {
                continue;
            };
            if result.kind != NodeResultKind::MainToolCall && result.kind != NodeResultKind::Blocker
            {
                continue;
            }
            for hint in
                validation_failure_property_rename_hints(&result.body, missing_required_properties)
            {
                if !hints.iter().any(|existing| existing == &hint) {
                    hints.push(hint);
                }
            }
        }
    }
    hints
}

fn validation_failure_property_rename_hints(
    text: &str,
    missing_required_properties: &[String],
) -> Vec<String> {
    let mut hints = Vec::new();
    let missing = missing_required_properties
        .iter()
        .map(|property| property.as_str())
        .collect::<HashSet<_>>();
    for line in text.lines() {
        let lower = line.to_ascii_lowercase();
        if !lower.contains("is a required property") {
            continue;
        }
        let Some(marker_start) = lower.find("is a required property") else {
            continue;
        };
        let before = &line[..marker_start];
        let Some(required) = quoted_suffix_value(before) else {
            continue;
        };
        if !missing.contains(required.as_str()) {
            continue;
        }
        for existing_key in quoted_object_keys(before) {
            if property_key_suggests_rename(&existing_key, &required) {
                let hint = format!("{existing_key}->{required}");
                if !hints.iter().any(|existing| existing == &hint) {
                    hints.push(hint);
                }
            }
        }
    }
    hints
}

fn quoted_object_keys(text: &str) -> Vec<String> {
    let mut keys = Vec::new();
    for quote in ['\'', '"'] {
        let mut rest = text;
        while let Some(start) = rest.find(quote) {
            let after_start = &rest[start + quote.len_utf8()..];
            let Some(end) = after_start.find(quote) else {
                break;
            };
            let value = &after_start[..end];
            let after_end = &after_start[end + quote.len_utf8()..];
            if after_end.trim_start().starts_with(':')
                && !keys.iter().any(|existing| existing == value)
            {
                keys.push(value.to_string());
            }
            rest = after_end;
        }
    }
    keys
}

fn property_key_suggests_rename(existing_key: &str, required_property: &str) -> bool {
    let existing = normalize_property_name(existing_key);
    let required = normalize_property_name(required_property);
    if existing.is_empty() || required.is_empty() {
        return false;
    }
    if existing == required {
        return true;
    }
    let required_singular = required.strip_suffix('s').unwrap_or(&required);
    required_singular.len() >= 4 && existing.contains(required_singular)
}

fn normalize_property_name(value: &str) -> String {
    value
        .chars()
        .filter(|ch| ch.is_ascii_alphanumeric())
        .flat_map(|ch| ch.to_lowercase())
        .collect()
}

fn implement_node_dependency_schema_required_groups_for_properties(
    map: &ActionMapInstance,
    node: &MapNode,
    missing_required_properties: &[String],
) -> Vec<SchemaRequiredGroup> {
    if missing_required_properties.is_empty() {
        return Vec::new();
    }
    let missing = missing_required_properties
        .iter()
        .map(|property| property.to_ascii_lowercase())
        .collect::<HashSet<_>>();
    let mut groups = Vec::new();
    let mut seen = HashSet::new();
    for dependency_node_id in implement_node_transitive_dependency_node_ids(map, node) {
        let Some(dependency) = map.nodes.get(&dependency_node_id) else {
            continue;
        };
        for result_ref in &dependency.result_context {
            let Some(result) = map.results.get(&result_ref.id) else {
                continue;
            };
            if result.kind != NodeResultKind::MainToolCall
                || result.tool_success != Some(true)
                || !matches!(
                    result.action_class,
                    Some(ActionClass::Read | ActionClass::Search)
                )
            {
                continue;
            }
            for group in schema_required_groups_from_tool_result(result) {
                if !group
                    .required
                    .iter()
                    .any(|property| missing.contains(&property.to_ascii_lowercase()))
                {
                    continue;
                }
                let key = format!(
                    "{}:{}:{}",
                    group.source_artifact,
                    group.path,
                    group.required.join(",")
                );
                if seen.insert(key) {
                    groups.push(group);
                }
            }
        }
    }
    groups
}

fn implement_node_validation_rework_dependency_node_ids(
    map: &ActionMapInstance,
    node: &MapNode,
) -> Vec<String> {
    let mut node_ids = map
        .edges
        .iter()
        .filter(|edge| edge.to == node.id)
        .map(|edge| edge.from.clone())
        .collect::<Vec<_>>();
    if let Some(origin_node_id) = node.origin_node_id.as_deref()
        && !node_ids.iter().any(|existing| existing == origin_node_id)
    {
        node_ids.push(origin_node_id.to_string());
    }
    node_ids
}

fn implement_node_transitive_dependency_node_ids(
    map: &ActionMapInstance,
    node: &MapNode,
) -> Vec<String> {
    let mut ordered = Vec::new();
    let mut seen = HashSet::new();
    let mut stack = implement_node_validation_rework_dependency_node_ids(map, node);
    while let Some(node_id) = stack.pop() {
        if !seen.insert(node_id.clone()) {
            continue;
        }
        ordered.push(node_id.clone());
        for edge in map.edges.iter().filter(|edge| edge.to == node_id) {
            stack.push(edge.from.clone());
        }
        if let Some(origin_node_id) = map
            .nodes
            .get(&node_id)
            .and_then(|dependency| dependency.origin_node_id.as_deref())
            && !seen.contains(origin_node_id)
        {
            stack.push(origin_node_id.to_string());
        }
    }
    ordered
}

fn implement_node_has_dependency_implementation_source_evidence(
    map: &ActionMapInstance,
    node: &MapNode,
) -> bool {
    map.edges.iter().any(|edge| {
        if edge.to != node.id {
            return false;
        }
        let Some(dependency) = map.nodes.get(&edge.from) else {
            return false;
        };
        dependency.result_context.iter().any(|result_ref| {
            map.results.get(&result_ref.id).is_some_and(|result| {
                successful_inspect_result_has_working_evidence(result)
                    && result_visible_artifact_refs(result)
                        .iter()
                        .any(|artifact_ref| is_inspected_implementation_source_ref(artifact_ref))
            })
        })
    })
}

fn implement_node_has_dependency_inspected_fact_source_evidence(
    map: &ActionMapInstance,
    node: &MapNode,
) -> bool {
    map.edges.iter().any(|edge| {
        if edge.to != node.id {
            return false;
        }
        let Some(dependency) = map.nodes.get(&edge.from) else {
            return false;
        };
        if dependency.kind != NodeKind::InspectCodeContext {
            return false;
        }
        dependency.result_context.iter().any(|result_ref| {
            map.results
                .get(&result_ref.id)
                .is_some_and(|result| inspect_result_or_bridge_has_fact_source_evidence(result))
        })
    })
}

fn inspect_result_or_bridge_has_fact_source_evidence(result: &NodeResult) -> bool {
    let inspect_tool_result = successful_inspect_result_has_working_evidence(result);
    let inspect_bridge_result = result.kind == NodeResultKind::Result
        && result.evidence_package.validity == ResultValidity::Accepted
        && result
            .body
            .contains("Inspect evidence supported convergence");
    if !inspect_tool_result && !inspect_bridge_result {
        return false;
    }
    result_visible_artifact_refs(result).iter().any(|artifact| {
        let artifact = artifact.to_ascii_lowercase();
        matches!(
            artifact.rsplit_once('.').map(|(_, ext)| ext),
            Some("csv" | "json" | "yaml" | "yml" | "toml" | "txt")
        )
    })
}

fn is_inspected_implementation_source_ref(artifact_ref: &str) -> bool {
    let normalized = normalize_artifact_ref(artifact_ref).to_ascii_lowercase();
    if normalized.starts_with("scripts/")
        || normalized.starts_with("tests/")
        || normalized.contains("/tests/")
        || normalized == "readme.md"
        || normalized.starts_with("docs/")
    {
        return false;
    }
    normalized.starts_with("src/")
        || normalized.contains("/src/")
        || normalized.ends_with(".py")
        || normalized.ends_with(".rs")
        || normalized.ends_with(".js")
        || normalized.ends_with(".jsx")
        || normalized.ends_with(".ts")
        || normalized.ends_with(".tsx")
        || normalized.ends_with(".go")
        || normalized.ends_with(".java")
        || normalized.ends_with(".kt")
        || normalized.ends_with(".swift")
        || normalized.ends_with(".rb")
        || normalized.ends_with(".php")
        || normalized.ends_with(".c")
        || normalized.ends_with(".cc")
        || normalized.ends_with(".cpp")
        || normalized.ends_with(".h")
        || normalized.ends_with(".hpp")
        || normalized.ends_with(".cs")
}

fn implement_node_uncovered_mandatory_evidence(
    map: &ActionMapInstance,
    node: &MapNode,
) -> Vec<String> {
    let changed_artifacts = successful_edit_artifact_set(map, node);
    let mut evidence_node_ids = map
        .edges
        .iter()
        .filter(|edge| edge.to == node.id)
        .map(|edge| edge.from.as_str())
        .collect::<Vec<_>>();
    evidence_node_ids.push(node.id.as_str());
    let mut uncovered = Vec::new();
    for evidence_node_id in evidence_node_ids {
        let Some(evidence_node) = map.nodes.get(evidence_node_id) else {
            continue;
        };
        for result_ref in &evidence_node.result_context {
            let Some(result) = map.results.get(&result_ref.id) else {
                continue;
            };
            if result.kind != NodeResultKind::MainToolCall
                || result.tool_success != Some(true)
                || result.action_class != Some(ActionClass::Read)
            {
                continue;
            }
            let Some(signal) = mandatory_evidence_signal(&result.body) else {
                continue;
            };
            for artifact in result_artifact_refs(result) {
                let normalized = artifact_key(&artifact);
                if !changed_artifacts.contains(&normalized) {
                    let item = format!("{artifact} ({signal}, {})", result.id);
                    if !uncovered.iter().any(|existing| existing == &item) {
                        uncovered.push(item);
                    }
                }
            }
        }
    }
    uncovered
}

fn successful_edit_artifact_set(map: &ActionMapInstance, node: &MapNode) -> HashSet<String> {
    let mut artifacts = HashSet::new();
    for result_ref in &node.result_context {
        let Some(result) = map.results.get(&result_ref.id) else {
            continue;
        };
        if result.kind != NodeResultKind::MainToolCall
            || result.tool_success != Some(true)
            || result.action_class != Some(ActionClass::Edit)
        {
            continue;
        }
        for artifact in result_artifact_refs(result) {
            artifacts.insert(artifact_key(&artifact));
        }
        for artifact in extract_edit_changed_artifacts_from_tool_body(&result.body) {
            artifacts.insert(artifact_key(&artifact));
        }
    }
    artifacts
}

fn result_artifact_refs(result: &NodeResult) -> Vec<String> {
    let mut artifacts = Vec::new();
    for evidence_ref in &result.evidence_package.evidence_refs {
        if let Some(artifact_ref) = evidence_ref.artifact_ref.as_deref() {
            let artifact_ref = normalize_artifact_ref(artifact_ref);
            if !artifact_ref.is_empty()
                && !artifacts.iter().any(|existing| existing == &artifact_ref)
            {
                artifacts.push(artifact_ref);
            }
        }
    }
    for artifact_ref in &result.evidence_package.changed_artifacts {
        let artifact_ref = normalize_artifact_ref(artifact_ref);
        if !artifact_ref.is_empty() && !artifacts.iter().any(|existing| existing == &artifact_ref) {
            artifacts.push(artifact_ref);
        }
    }
    artifacts
}

fn result_visible_artifact_refs(result: &NodeResult) -> Vec<String> {
    let mut artifacts = result_artifact_refs(result);
    for artifact_ref in result_body_section_artifact_refs(&result.body) {
        if !artifact_ref.is_empty() && !artifacts.iter().any(|existing| existing == &artifact_ref) {
            artifacts.push(artifact_ref);
        }
    }
    for artifact_ref in result_body_inline_artifact_refs(&result.body) {
        if !artifact_ref.is_empty() && !artifacts.iter().any(|existing| existing == &artifact_ref) {
            artifacts.push(artifact_ref);
        }
    }
    artifacts
}

fn result_body_inline_artifact_refs(body: &str) -> Vec<String> {
    let mut artifacts = Vec::new();
    for segment in body.split("artifacts=").skip(1) {
        let value = segment.split([':', '|', ';']).next().unwrap_or("").trim();
        for raw_artifact in value.split(',') {
            let artifact_ref = normalize_artifact_ref(raw_artifact.trim());
            if !artifact_ref.is_empty()
                && !artifacts.iter().any(|existing| existing == &artifact_ref)
            {
                artifacts.push(artifact_ref);
            }
        }
    }
    artifacts
}

fn result_body_section_artifact_refs(body: &str) -> Vec<String> {
    let mut artifacts = Vec::new();
    for line in body.lines().map(str::trim) {
        let Some(raw_path) = line.strip_prefix("=====") else {
            continue;
        };
        let artifact_ref = normalize_artifact_ref(raw_path.trim());
        if !artifact_ref.is_empty() && !artifacts.iter().any(|existing| existing == &artifact_ref) {
            artifacts.push(artifact_ref);
        }
    }
    artifacts
}

fn artifact_key(path: &str) -> String {
    normalize_artifact_ref(path).to_ascii_lowercase()
}

fn artifact_file_key(path: &str) -> String {
    let key = artifact_key(path);
    if let Some((file, line)) = key.rsplit_once(':')
        && !file.is_empty()
        && !line.is_empty()
        && line.chars().all(|ch| ch.is_ascii_digit())
    {
        return file.to_string();
    }
    key
}

fn mandatory_evidence_signal(body: &str) -> Option<&'static str> {
    let lower = body.to_ascii_lowercase();
    if lower.contains("#!/bin/nonexistent") {
        Some("invalid_shebang")
    } else if lower.contains("traceback") {
        Some("traceback")
    } else if lower.contains("syntax error") {
        Some("syntax_error")
    } else if lower.contains("command not found") {
        Some("command_not_found")
    } else {
        None
    }
}

fn successful_read_result_has_working_evidence(result: &NodeResult) -> bool {
    if result.kind != NodeResultKind::MainToolCall
        || result.tool_success != Some(true)
        || result.action_class != Some(ActionClass::Read)
    {
        return false;
    }
    if read_result_body_is_path_listing_only(&result.body) {
        return false;
    }
    code_or_test_read_body_has_content_signal(&result.body)
        || !result_input_data_artifact_refs(result).is_empty()
}

fn successful_inspect_result_has_working_evidence(result: &NodeResult) -> bool {
    if result.kind != NodeResultKind::MainToolCall
        || result.tool_success != Some(true)
        || !matches!(
            result.action_class,
            Some(ActionClass::Read | ActionClass::Search)
        )
    {
        return false;
    }
    if read_result_body_is_path_listing_only(&result.body) {
        return false;
    }
    code_or_test_read_body_has_content_signal(&result.body)
        || !result_input_data_artifact_refs(result).is_empty()
}

fn read_result_body_is_path_listing_only(body: &str) -> bool {
    let lower = body.to_ascii_lowercase();
    if body
        .lines()
        .map(str::trim)
        .map(|line| line.to_ascii_lowercase())
        .any(|line| read_body_line_has_code_content_signal(&line))
    {
        return false;
    }
    if body
        .lines()
        .any(|line| line.trim_start().starts_with("====="))
    {
        return false;
    }
    if lower.contains("command: rg --files")
        || lower.contains("command: get-childitem")
        || lower.contains("command: dir ")
        || lower.contains("command: ls ")
    {
        return true;
    }

    let mut path_like_lines = 0usize;
    let mut considered_lines = 0usize;
    for line in body.lines().map(str::trim).filter(|line| !line.is_empty()) {
        let lower_line = line.to_ascii_lowercase();
        if lower_line.starts_with("taskspacetoolinvocationv1")
            || lower_line.starts_with("main tool call")
            || lower_line.starts_with("tool:")
            || lower_line.starts_with("call_id:")
            || lower_line.starts_with("action_class:")
            || lower_line.starts_with("success:")
            || lower_line.starts_with("command:")
            || lower_line.starts_with("raw_output:")
            || lower_line == "preview:"
            || lower_line.starts_with("exit code:")
            || lower_line.starts_with("wall time:")
            || lower_line == "output:"
        {
            continue;
        }
        if read_body_line_has_code_content_signal(&lower_line) {
            return false;
        }
        considered_lines += 1;
        if is_probable_path_listing_line(line) {
            path_like_lines += 1;
        } else {
            return false;
        }
    }

    considered_lines >= 2 && path_like_lines == considered_lines
}

fn read_body_line_has_code_content_signal(lower_line: &str) -> bool {
    lower_line.contains("def ")
        || lower_line.contains("fn ")
        || lower_line.contains("function ")
        || lower_line.contains("#!/bin/")
        || lower_line.contains("#!/usr/bin/env bash")
        || lower_line.contains("set -e")
        || lower_line.contains("return ")
        || lower_line.contains("import ")
        || lower_line.contains("const ")
        || lower_line.contains("let ")
        || lower_line.contains("class ")
        || lower_line.contains("assert ")
        || lower_line.contains("#[test]")
        || lower_line.contains("describe(")
        || lower_line.contains("it(")
}

fn is_probable_path_listing_line(line: &str) -> bool {
    let normalized = normalize_artifact_ref(line);
    let lower = normalized.to_ascii_lowercase();
    if lower.is_empty() || lower.len() > 240 || lower.contains(" ") {
        return false;
    }
    lower.contains('/')
        || matches!(
            lower.rsplit_once('.').map(|(_, ext)| ext),
            Some(
                "py" | "rs"
                    | "js"
                    | "ts"
                    | "tsx"
                    | "jsx"
                    | "go"
                    | "java"
                    | "cpp"
                    | "c"
                    | "h"
                    | "hpp"
                    | "md"
                    | "toml"
                    | "json"
                    | "yaml"
                    | "yml"
                    | "txt"
                    | "sh"
                    | "ps1"
            )
        )
}

fn result_input_data_artifact_refs(result: &NodeResult) -> Vec<String> {
    let mut artifacts = result_visible_artifact_refs(result)
        .into_iter()
        .filter(|artifact| is_input_data_artifact_ref(artifact))
        .collect::<Vec<_>>();
    if let Some(command) = result_body_command(result) {
        for artifact in command_input_data_artifact_refs(&command) {
            if !artifacts.iter().any(|existing| existing == &artifact) {
                artifacts.push(artifact);
            }
        }
    }
    artifacts
}

fn command_input_data_artifact_refs(command: &str) -> Vec<String> {
    let mut artifacts = Vec::new();
    for token in command.split_whitespace() {
        let candidate = normalize_artifact_ref(token.trim_matches(|ch: char| {
            ch == '\'' || ch == '"' || ch == '`' || ch == ',' || ch == ';'
        }));
        if candidate.is_empty()
            || candidate.starts_with('-')
            || candidate.contains('*')
            || candidate.contains('?')
            || !is_input_data_artifact_ref(&candidate)
        {
            continue;
        }
        if !artifacts.iter().any(|existing| existing == &candidate) {
            artifacts.push(candidate);
        }
    }
    artifacts
}

fn is_input_data_artifact_ref(artifact_ref: &str) -> bool {
    let normalized = artifact_ref.replace('\\', "/").to_ascii_lowercase();
    if normalized == "readme.md"
        || normalized.starts_with("docs/")
        || normalized.starts_with("tests/")
        || normalized.contains("/tests/")
    {
        return false;
    }
    matches!(
        normalized.rsplit_once('.').map(|(_, ext)| ext),
        Some("log" | "jsonl" | "json" | "csv" | "tsv" | "yaml" | "yml" | "txt")
    )
}

fn code_or_test_read_body_has_content_signal(body: &str) -> bool {
    let body = body.to_ascii_lowercase();
    read_body_line_has_code_content_signal(&body) || body.contains("test_")
}

const TASKSPACE_WORKING_EVIDENCE_SUMMARY_MAX_RESULTS: usize = 8;
const TASKSPACE_WORKING_EVIDENCE_SUMMARY_MAX_CHARS: usize = 1200;
const TASKSPACE_VALIDATION_REWORK_TARGET_READ_MAX_CHARS: usize = 16_000;
const TASKSPACE_VALIDATION_REWORK_TARGET_READ_SUMMARY_MAX_CHARS: usize = 6000;

fn inspect_code_or_test_read_summary(map: &ActionMapInstance, node: &MapNode) -> String {
    let summary = working_evidence_summary_for_nodes(map, &[node.id.as_str()]);
    if summary.is_empty() {
        "successful working evidence is recorded on the inspect node".to_string()
    } else {
        summary
    }
}

fn working_evidence_node_ids_for_current_node<'a>(
    map: &'a ActionMapInstance,
    node: &'a MapNode,
) -> Vec<&'a str> {
    let mut ordered = Vec::new();
    let mut stack = vec![node.id.as_str()];
    let mut visited = HashSet::new();
    while let Some(node_id) = stack.pop() {
        if !visited.insert(node_id) {
            continue;
        }
        ordered.push(node_id);
        if let Some(origin_node_id) = map
            .nodes
            .get(node_id)
            .and_then(|current| current.origin_node_id.as_deref())
        {
            stack.push(origin_node_id);
        }
        for edge in &map.edges {
            if edge.to == node_id {
                stack.push(edge.from.as_str());
            }
        }
    }
    ordered
}

fn working_evidence_summary_for_nodes(map: &ActionMapInstance, node_ids: &[&str]) -> String {
    let mut summaries: Vec<(usize, usize, String)> = node_ids
        .iter()
        .filter_map(|node_id| map.nodes.get(*node_id))
        .flat_map(|node| node.result_context.iter())
        .enumerate()
        .filter_map(|(index, result_ref)| {
            map.results
                .get(&result_ref.id)
                .map(|result| (index, result))
        })
        .filter(|(_, result)| successful_inspect_result_has_working_evidence(result))
        .map(|(index, result)| {
            let mut artifacts = result_visible_artifact_refs(result);
            for artifact in result_input_data_artifact_refs(result) {
                if !artifacts.iter().any(|existing| existing == &artifact) {
                    artifacts.push(artifact);
                }
            }
            let artifact_text = if artifacts.is_empty() {
                String::new()
            } else {
                format!(" artifacts={}", artifacts.join(","))
            };
            (
                working_evidence_priority(&result.body),
                index,
                format!(
                    "{}{}: {}",
                    result.id,
                    artifact_text,
                    single_line_preview(
                        &working_evidence_body_excerpt(
                            &result.body,
                            TASKSPACE_WORKING_EVIDENCE_SUMMARY_MAX_CHARS,
                        ),
                        TASKSPACE_WORKING_EVIDENCE_SUMMARY_MAX_CHARS
                    )
                ),
            )
        })
        .collect();
    summaries.sort_by_key(|(priority, index, _)| (*priority, *index));
    summaries
        .into_iter()
        .take(TASKSPACE_WORKING_EVIDENCE_SUMMARY_MAX_RESULTS)
        .map(|(_, _, summary)| summary)
        .collect::<Vec<_>>()
        .join(" | ")
}

fn validation_rework_target_read_evidence_summary(
    map: &ActionMapInstance,
    node: &MapNode,
    max_results: usize,
    max_excerpt_chars: usize,
) -> String {
    if node.kind != NodeKind::ImplementSolution {
        return String::new();
    }
    let validation_rework_artifacts =
        implement_node_dependency_validation_rework_artifact_refs(map, node);
    if validation_rework_artifacts.is_empty() {
        return String::new();
    }
    implement_node_validation_rework_artifact_read_results(
        map,
        node,
        &validation_rework_artifacts,
    )
    .into_iter()
    .take(max_results)
    .filter_map(|(artifact, result_id)| {
        let result = map.results.get(&result_id)?;
        let read_context = validation_rework_read_context_status(&result.body)
            .map(|status| format!("\nread_context: {status}"))
            .unwrap_or_default();
        let (target_excerpt, content_visibility) =
            validation_rework_target_read_excerpt_and_visibility(&result.body, max_excerpt_chars);
        Some(format!(
            "validation_rework_target_read result={result_id} artifact={artifact}{read_context}\ncontent_visibility: {content_visibility}\nexcerpt:\n{target_excerpt}"
        ))
    })
    .collect::<Vec<_>>()
    .join("\n")
}

fn validation_rework_target_read_excerpt_and_visibility(
    result_body: &str,
    max_excerpt_chars: usize,
) -> (String, &'static str) {
    let read_context = validation_rework_read_context_status(result_body).unwrap_or_default();
    let complete_read =
        read_context.contains("complete_read") || read_context.contains("eof_reached=true");
    let max_chars = if complete_read {
        max_excerpt_chars.max(TASKSPACE_VALIDATION_REWORK_TARGET_READ_MAX_CHARS)
    } else {
        max_excerpt_chars
    };
    let excerpt = working_evidence_body_excerpt(result_body, max_chars);
    let truncated_by_budget = excerpt.trim_end().ends_with("...");
    let visibility = if complete_read && !truncated_by_budget {
        "full_content_visible"
    } else if complete_read {
        "summary_excerpt_only"
    } else {
        "partial_read_excerpt"
    };
    (excerpt, visibility)
}

fn working_evidence_priority(body: &str) -> usize {
    let lower = body.to_ascii_lowercase();
    if lower.contains("#!/bin/nonexistent")
        || lower.contains("traceback")
        || lower.contains("syntax error")
        || lower.contains("no such file")
        || lower.contains("command not found")
    {
        0
    } else {
        1
    }
}

fn node_has_problem_state_effect(
    task: &TaskState,
    map: &ActionMapInstance,
    node: &MapNode,
) -> bool {
    task.problem_ledger
        .known_facts
        .iter()
        .any(|fact| evidence_refs_include_node_result(map, node, &fact.evidence_refs))
        || task.problem_ledger.open_questions.iter().any(|question| {
            question.opened_by_node_id.as_deref() == Some(node.id.as_str())
                || evidence_refs_include_node_result(map, node, &question.evidence_refs)
        })
        || task.problem_ledger.decisions.iter().any(|decision| {
            decision
                .depends_on_results
                .iter()
                .any(|result_id| node_has_result_id(node, result_id))
                || task.problem_ledger.open_questions.iter().any(|question| {
                    decision
                        .resolves_questions
                        .iter()
                        .any(|id| id == &question.id)
                        && question.opened_by_node_id.as_deref() == Some(node.id.as_str())
                })
        })
}

fn node_satisfies_success_criterion_with_validation_result(
    task: &TaskState,
    map: &ActionMapInstance,
    node: &MapNode,
) -> bool {
    task.problem_ledger
        .success_criteria
        .iter()
        .any(|criterion| {
            criterion.status == "satisfied"
                && evidence_refs_include_successful_validation_result(
                    map,
                    node,
                    &criterion.evidence_refs,
                )
        })
}

fn task_success_criteria_complete(task: &TaskState) -> bool {
    let criteria = &task.problem_ledger.success_criteria;
    !criteria.is_empty()
        && criteria.iter().all(|criterion| {
            matches!(criterion.status.as_str(), "satisfied" | "waived")
                && !criterion.evidence_refs.is_empty()
        })
}

fn task_success_criteria_complete_for_final(task: &TaskState, map: &ActionMapInstance) -> bool {
    if task_success_criteria_complete(task) {
        return true;
    }
    let criteria = &task.problem_ledger.success_criteria;
    !criteria.is_empty()
        && criteria.iter().all(|criterion| {
            if matches!(criterion.status.as_str(), "satisfied" | "waived")
                && !criterion.evidence_refs.is_empty()
            {
                return true;
            }
            matches!(criterion.kind.as_str(), "test" | "validator")
                && criterion.status == "open"
                && !criterion.evidence_refs.is_empty()
                && map_has_accepted_successful_validation_result(map)
                || matches!(criterion.kind.as_str(), "artifact" | "behavior")
                    && criterion.status == "open"
                    && !criterion.evidence_refs.is_empty()
                    && map_has_accepted_implementation_result(map)
                    && map_has_accepted_successful_validation_result(map)
        })
}

fn task_open_blocking_question_id(task: &TaskState) -> Option<&str> {
    task.problem_ledger
        .open_questions
        .iter()
        .find(|question| question.blocking && question.status == "open")
        .map(|question| question.id.as_str())
}

fn evidence_refs_include_node_result(
    map: &ActionMapInstance,
    node: &MapNode,
    evidence_refs: &[EvidenceRef],
) -> bool {
    evidence_refs.iter().any(|evidence_ref| {
        evidence_ref.result_id.as_deref().is_some_and(|result_id| {
            node_has_result_id(node, result_id)
                && map
                    .results
                    .get(result_id)
                    .is_some_and(|result| result.node_id == node.id)
        })
    })
}

fn evidence_refs_include_successful_validation_result(
    map: &ActionMapInstance,
    node: &MapNode,
    evidence_refs: &[EvidenceRef],
) -> bool {
    let has_result_refs = evidence_refs
        .iter()
        .any(|evidence_ref| evidence_ref.result_id.is_some());
    evidence_refs.iter().any(|evidence_ref| {
        evidence_ref.result_id.as_deref().is_some_and(|result_id| {
            node_has_result_id(node, result_id)
                && map.results.get(result_id).is_some_and(|result| {
                    result.node_id == node.id
                        && result.kind == NodeResultKind::MainToolCall
                        && matches!(
                            result.action_class,
                            Some(ActionClass::Build | ActionClass::Test)
                        )
                        && result.tool_success == Some(true)
                })
        }) || !has_result_refs
            && evidence_ref
                .validator_ref
                .as_deref()
                .is_some_and(|value| !value.trim().is_empty())
            && node_has_successful_validation_action(map, node)
    })
}

fn node_has_result_id(node: &MapNode, result_id: &str) -> bool {
    node.result_context
        .iter()
        .any(|result_ref| result_ref.id == result_id)
}

fn node_result_is_local_validator_infra_failure(result: &NodeResult) -> bool {
    result.tool_success != Some(true)
        && matches!(
            result.action_class,
            Some(ActionClass::Build | ActionClass::Test)
        )
        && is_local_validator_infra_failure(&result.body)
}

fn node_result_is_tool_runtime_bootstrap_failure(result: &NodeResult) -> bool {
    result.kind == NodeResultKind::MainToolCall
        && result.tool_success != Some(true)
        && text_mentions_tool_runtime_bootstrap_failure(&result.body)
}

fn state_commit_has_validation_failure_rework(
    input: &ActionMapStateCommitInput,
    map: &ActionMapInstance,
    current_node_id: &str,
) -> bool {
    if input
        .blockers
        .iter()
        .any(|blocker| blocker.node_id == current_node_id)
    {
        return true;
    }
    if input.nodes.iter().any(|node| {
        node.kind == NodeKind::ImplementSolution
            && (node.dependency_node_ids.is_empty()
                || node
                    .dependency_node_ids
                    .iter()
                    .any(|dependency| dependency == current_node_id))
    }) {
        return true;
    }
    if input.active_node_id.as_deref().is_some_and(|node_id| {
        map.nodes
            .get(node_id)
            .is_some_and(|node| node.kind == NodeKind::ImplementSolution)
    }) {
        return true;
    }
    input.finished_nodes.iter().any(|finished| {
        finished.node_id == current_node_id
            && (finished.next_node_id.as_deref().is_some_and(|node_id| {
                map.nodes
                    .get(node_id)
                    .is_some_and(|node| node.kind == NodeKind::ImplementSolution)
            }) || finished
                .next_node_draft
                .as_ref()
                .is_some_and(|draft| draft.kind == NodeKind::ImplementSolution))
    })
}

fn map_has_successful_edit(map: &ActionMapInstance) -> bool {
    map.nodes
        .values()
        .any(|node| node_has_successful_action(map, node, ActionClass::Edit))
}

fn successful_dependency_edit_result_ids(
    map: &ActionMapInstance,
    validation_node_id: &str,
) -> Vec<NodeResultId> {
    dependency_implementation_result_ids(map, validation_node_id, |result| {
        result.kind == NodeResultKind::MainToolCall
            && result.tool_success == Some(true)
            && result.action_class == Some(ActionClass::Edit)
            && result.evidence_package.validity == ResultValidity::Unreviewed
    })
}

fn dependency_implementation_lifecycle_result_ids(
    map: &ActionMapInstance,
    validation_node_id: &str,
) -> Vec<NodeResultId> {
    dependency_implementation_result_ids(map, validation_node_id, |result| {
        result.kind == NodeResultKind::Result
            && result.evidence_package.validity == ResultValidity::Unreviewed
    })
}

fn dependency_implementation_result_ids(
    map: &ActionMapInstance,
    validation_node_id: &str,
    include_result: impl Fn(&NodeResult) -> bool,
) -> Vec<NodeResultId> {
    let dependency_node_ids = map
        .edges
        .iter()
        .filter(|edge| edge.to == validation_node_id)
        .map(|edge| edge.from.as_str())
        .collect::<HashSet<_>>();
    let mut result_ids = Vec::new();
    for node_id in dependency_node_ids {
        let Some(node) = map.nodes.get(node_id) else {
            continue;
        };
        if node.kind != NodeKind::ImplementSolution {
            continue;
        }
        for result_ref in &node.result_context {
            let Some(result) = map.results.get(&result_ref.id) else {
                continue;
            };
            if include_result(result) {
                result_ids.push(result_ref.id.clone());
            }
        }
    }
    result_ids.sort();
    result_ids.dedup();
    result_ids
}

fn superseded_validation_blocker_result_ids(
    map: &ActionMapInstance,
    validation_node_id: &str,
) -> Vec<NodeResultId> {
    let mut stack = map
        .edges
        .iter()
        .filter(|edge| edge.to == validation_node_id)
        .map(|edge| edge.from.clone())
        .collect::<Vec<_>>();
    if let Some(origin_node_id) = map
        .nodes
        .get(validation_node_id)
        .and_then(|node| node.origin_node_id.clone())
    {
        stack.push(origin_node_id);
    }
    let mut visited = HashSet::new();
    let mut result_ids = Vec::new();
    while let Some(node_id) = stack.pop() {
        if !visited.insert(node_id.clone()) {
            continue;
        }
        let Some(node) = map.nodes.get(&node_id) else {
            continue;
        };
        if node.kind == NodeKind::ImplementSolution
            && let Some(origin_node_id) = node.origin_node_id.as_deref()
            && let Some(origin) = map.nodes.get(origin_node_id)
        {
            if matches!(origin.kind, NodeKind::SmokeTest | NodeKind::RegressionTest)
                && origin.status == NodeStatus::Blocked
            {
                for result_ref in &origin.result_context {
                    let Some(result) = map.results.get(&result_ref.id) else {
                        continue;
                    };
                    if result.kind == NodeResultKind::Blocker
                        && result.evidence_package.validity == ResultValidity::Unreviewed
                    {
                        result_ids.push(result_ref.id.clone());
                    }
                }
            }
            stack.push(origin_node_id.to_string());
        }
        for edge in &map.edges {
            if edge.to == node_id {
                stack.push(edge.from.clone());
            }
        }
    }
    result_ids.sort();
    result_ids.dedup();
    result_ids
}

fn map_has_accepted_successful_validation_result(map: &ActionMapInstance) -> bool {
    map.nodes.values().any(|node| {
        matches!(node.kind, NodeKind::SmokeTest | NodeKind::RegressionTest)
            && node.result_context.iter().any(|result_ref| {
                map.results.get(&result_ref.id).is_some_and(|result| {
                    result.evidence_package.validity == ResultValidity::Accepted
                        && node_result_is_successful_validation(result)
                })
            })
    })
}

fn map_has_blocked_validation_result(map: &ActionMapInstance) -> bool {
    map.nodes.values().any(|node| {
        matches!(node.kind, NodeKind::SmokeTest | NodeKind::RegressionTest)
            && node.status == NodeStatus::Blocked
            && node.result_context.iter().any(|result_ref| {
                map.results.get(&result_ref.id).is_some_and(|result| {
                    result.kind == NodeResultKind::Blocker
                        && result.evidence_package.validity != ResultValidity::Invalid
                })
            })
    })
}

fn map_has_tool_runtime_bootstrap_failure(map: &ActionMapInstance) -> bool {
    map.nodes.values().any(|node| {
        node.status == NodeStatus::Blocked
            && node.result_context.iter().any(|result_ref| {
                map.results.get(&result_ref.id).is_some_and(|result| {
                    node_result_is_tool_runtime_bootstrap_failure(result)
                        || result.kind == NodeResultKind::Blocker
                            && text_mentions_tool_runtime_bootstrap_failure(&result.body)
                })
            })
    })
}

fn map_has_ready_recovery_node(map: &ActionMapInstance) -> bool {
    map.nodes.values().any(|node| {
        node.status == NodeStatus::Ready
            && node.active_lease.is_none()
            && matches!(
                node.kind,
                NodeKind::ImplementSolution | NodeKind::SmokeTest | NodeKind::RegressionTest
            )
    })
}

fn should_auto_block_local_infra_validation_after_state_commit(
    outcome: &ActionMapStateCommitOutcome,
) -> bool {
    if outcome.accepted_sections.is_empty() || !outcome.rejected_sections.is_empty() {
        return false;
    }
    !outcome
        .accepted_sections
        .iter()
        .any(|section| matches!(section.as_str(), "blockers" | "finished_nodes" | "nodes"))
}

fn resolve_action_contract_call_result_id(map: &ActionMapInstance, value: &str) -> Option<String> {
    let value = value.trim();
    if !value.starts_with("taskspace-action-contract-") {
        return None;
    }
    map.results
        .values()
        .filter(|result| result.body.contains(value))
        .max_by_key(|result| result.created_at_ms)
        .map(|result| result.id.clone())
}

fn text_mentions_tool_runtime_bootstrap_failure(text: &str) -> bool {
    let lower = text.to_ascii_lowercase();
    let compact = lower
        .chars()
        .filter(|ch| ch.is_ascii_alphanumeric() || *ch == '_')
        .collect::<String>();
    (lower.contains("bwrap") || lower.contains("bubblewrap"))
        && (lower.contains("loopback")
            || lower.contains("rtm_newaddr")
            || compact.contains("failedrtmnewaddr"))
        && lower.contains("operation not permitted")
}

fn tool_runtime_bootstrap_failure_blocker_summary(body: &str) -> String {
    format!(
        "Tool runtime bootstrap failed before TaskSpace could execute ordinary tools. failure_kind=sandbox_bootstrap_failed; task_level_blocker=true; no_create_node_after_terminal_infra=true. Failure preview: {}",
        single_line_preview(body, 220)
    )
}

fn text_mentions_local_validator_infra_failure(text: &str) -> bool {
    let text = text.to_ascii_lowercase();
    let compact = text
        .chars()
        .filter(|ch| ch.is_ascii_alphanumeric() || *ch == '_')
        .collect::<String>();
    let uv_cache_permission_failure = (text.contains("uv\\cache")
        || text.contains("uv/cache")
        || text.contains("sdists-v9")
        || text.contains("appdata\\local\\uv\\cache"))
        && (text.contains("os error 5")
            || text.contains("access is denied")
            || text.contains("access denied")
            || text.contains("permission denied")
            || text.contains("拒绝访问"));
    text.contains("bash/service/createinstance/e_accessdenied")
        || text.contains("wsl/service/e_accessdenied")
        || text.contains("e_accessdenied")
        || text.contains("invalidendofline")
        || text_mentions_tool_runtime_bootstrap_failure(&text)
        || text_mentions_missing_pytest_runner_dependency(&text)
        || uv_cache_permission_failure
        || compact.contains("bashservicecreateinstanceeaccessdenied")
        || compact.contains("bashservicecreateinstancee_accessdenied")
        || compact.contains("wslserviceeaccessdenied")
        || compact.contains("wslservicee_accessdenied")
        || compact.contains("eaccessdenied")
        || compact.contains("e_accessdenied")
        || compact.contains("invalidendofline")
}

fn local_validator_infra_failure_can_rework_command(text: &str) -> bool {
    let text = text.to_ascii_lowercase();
    let compact = text
        .chars()
        .filter(|ch| ch.is_ascii_alphanumeric() || *ch == '_')
        .collect::<String>();
    text.contains("invalidendofline")
        || text_mentions_missing_pytest_runner_dependency(&text)
        || text.contains("not a valid statement separator")
        || compact.contains("invalidendofline")
        || (text.contains("e_accessdenied")
            && (text.contains("command: bash ")
                || text.contains("bash setup-")
                || text.contains("bash run-")
                || text.contains("bash -lc")))
}

fn text_mentions_missing_pytest_runner_dependency(text: &str) -> bool {
    let lower = text.to_ascii_lowercase();
    let command_mentions_pytest_runner = lower.contains("command: python -m pytest")
        || lower.contains("command: pytest")
        || lower.contains("command: uv run pytest")
        || lower.contains("command: python3 -m pytest")
        || lower.contains("python -m pytest");
    let missing_pytest = lower.contains("no module named pytest")
        || lower.contains("no module named 'pytest'")
        || lower.contains("no module named \"pytest\"")
        || lower.contains("pytest: command not found")
        || lower.contains("pytest: not found")
        || lower.contains("command not found: pytest")
        || lower.contains("pytest' is not recognized")
        || lower.contains("\"pytest\" is not recognized")
        || (lower.contains("modulenotfounderror") && lower.contains("pytest"));
    command_mentions_pytest_runner && missing_pytest
}

fn map_has_accepted_implementation_result(map: &ActionMapInstance) -> bool {
    map.nodes.values().any(|node| {
        node.kind == NodeKind::ImplementSolution
            && node_has_successful_action(map, node, ActionClass::Edit)
            && node.result_context.iter().any(|result_ref| {
                map.results.get(&result_ref.id).is_some_and(|result| {
                    result.evidence_package.validity == ResultValidity::Accepted
                        && result.kind != NodeResultKind::Blocker
                })
            })
    })
}

fn node_has_successful_validation_action(map: &ActionMapInstance, node: &MapNode) -> bool {
    node.result_context.iter().any(|result_ref| {
        map.results
            .get(&result_ref.id)
            .is_some_and(node_result_is_successful_validation)
    })
}

fn latest_successful_validation_result_id(
    map: &ActionMapInstance,
    node: &MapNode,
) -> Option<NodeResultId> {
    node.result_context.iter().rev().find_map(|result_ref| {
        let result = map.results.get(&result_ref.id)?;
        if node_result_is_successful_validation(result) {
            Some(result_ref.id.clone())
        } else {
            None
        }
    })
}

fn latest_accepted_successful_validation_result_id(
    map: &ActionMapInstance,
    node: &MapNode,
) -> Option<NodeResultId> {
    node.result_context.iter().rev().find_map(|result_ref| {
        let result = map.results.get(&result_ref.id)?;
        if result.evidence_package.validity == ResultValidity::Accepted
            && node_result_is_successful_validation(result)
        {
            Some(result_ref.id.clone())
        } else {
            None
        }
    })
}

fn criterion_kind_can_be_satisfied_by_validated_artifact(kind: &str) -> bool {
    matches!(
        kind,
        "test" | "validator" | "artifact" | "behavior" | "user_visible_output"
    )
}

fn closeout_success_criterion_evidence_refs(
    validation_result_id: &str,
    implementation_result_ids: &[NodeResultId],
    validator_ref: &str,
) -> Vec<ActionMapEvidenceRefInput> {
    let mut refs = Vec::new();
    for result_id in implementation_result_ids {
        refs.push(ActionMapEvidenceRefInput {
            result_id: Some(result_id.clone()),
            ..Default::default()
        });
    }
    refs.push(ActionMapEvidenceRefInput {
        result_id: Some(validation_result_id.to_string()),
        validator_ref: Some(validator_ref.to_string()),
        ..Default::default()
    });
    refs
}

fn rewrite_result_id_refs(
    refs: &mut [ActionMapEvidenceRefInput],
    from_result_id: &str,
    to_result_id: &str,
) {
    for evidence_ref in refs {
        if evidence_ref.result_id.as_deref() == Some(from_result_id) {
            evidence_ref.result_id = Some(to_result_id.to_string());
        }
    }
}

