    #[test]
    fn finish_smoke_node_requires_successful_validation_evidence() {
        let mut state = ActionMapRuntimeState::default();
        let owner = ThreadId::new();
        state.set_mode(MapRuntimeMode::Experiment);
        let (_, _, node_id, _) = start_test_task_with_kind(
            &mut state,
            owner,
            NodeKind::SmokeTest,
            "Validate fix",
            "Run the validation suite.",
            "Run smoke tests",
            "Run pytest.",
            true,
        );

        state
            .record_main_tool_result_with_class(
                owner,
                "call-test-fail",
                "shell_command",
                Some(ActionClass::Test),
                false,
                "pytest failed".to_string(),
            )
            .expect("failed test result records");

        let map = state.active_map().expect("active map");
        assert_eq!(
            map.nodes.get(&node_id).expect("validation node").status,
            NodeStatus::Blocked
        );
        assert_ne!(
            state.current_main_node_id.as_deref(),
            Some(node_id.as_str())
        );

        let mut state = ActionMapRuntimeState::default();
        let owner = ThreadId::new();
        state.set_mode(MapRuntimeMode::Experiment);
        let (_, _, node_id, _) = start_test_task_with_kind(
            &mut state,
            owner,
            NodeKind::SmokeTest,
            "Validate fix",
            "Run the validation suite.",
            "Run smoke tests",
            "Run pytest.",
            true,
        );

        let (result_id, _) = state
            .record_main_tool_result_with_class(
                owner,
                "call-test-pass",
                "shell_command",
                Some(ActionClass::Test),
                true,
                "pytest passed".to_string(),
            )
            .expect("successful test result records")
            .expect("test result id");
        state
            .finish_main_node(owner, &node_id, "Tests passed.".to_string(), None)
            .expect("smoke test auto-accepts successful validation evidence");
        let map = state.active_map().expect("active map");
        let task = state.tasks.get("task-1").expect("task");
        assert!(
            map.results
                .get(&result_id)
                .is_some_and(|result| result.evidence_package.validity == ResultValidity::Accepted)
        );
        assert!(
            task.problem_ledger
                .success_criteria
                .iter()
                .any(|criterion| {
                    criterion.status == "satisfied"
                        && evidence_refs_include_successful_validation_result(
                            map,
                            map.nodes.get(&node_id).expect("node"),
                            &criterion.evidence_refs,
                        )
                })
        );

        let (_, _, second_node_id, _) = start_test_task_with_kind(
            &mut state,
            owner,
            NodeKind::SmokeTest,
            "Validate fix again",
            "Run the validation suite.",
            "Run smoke tests",
            "Run pytest.",
            true,
        );
        let (result_id, _) = state
            .record_main_tool_result_with_class(
                owner,
                "call-test-pass-2",
                "shell_command",
                Some(ActionClass::Test),
                true,
                "pytest passed".to_string(),
            )
            .expect("second successful test result records")
            .expect("test result id");
        satisfy_test_criterion_with_result(&mut state, owner, &result_id);
        state
            .finish_main_node(owner, &second_node_id, "Tests passed.".to_string(), None)
            .expect("smoke test can finish after successful validation");
    }

