    #[test]
    fn validation_closeout_invalidates_superseded_rework_blocker_for_final_answer() {
        let mut state = ActionMapRuntimeState::default();
        let owner = ThreadId::new();
        state.set_mode(MapRuntimeMode::Experiment);
        let (_, map_id, validation_node_id, _) = start_test_task_with_kind(
            &mut state,
            owner,
            NodeKind::SmokeTest,
            "Validate generated organization output",
            "Run the validation suite.",
            "Run smoke tests",
            "Run organization validator.",
            true,
        );
        state
            .record_main_tool_result_with_class(
                owner,
                "call-test-fail",
                "shell_command",
                Some(ActionClass::Test),
                false,
                "KeyError: 'Engineering' in statistics.departmentSizes".to_string(),
            )
            .expect("failed validation records and routes to rework");
        let rework_node_id = state
            .current_main_node_id
            .as_deref()
            .expect("failed validation should bind rework")
            .to_string();
        let blocker_result_id = {
            let map = state.maps.get(&map_id).expect("active map");
            map.nodes
                .get(&validation_node_id)
                .expect("validation node")
                .result_context
                .iter()
                .find(|result_ref| result_ref.kind == NodeResultKind::Blocker)
                .expect("validation blocker result")
                .id
                .clone()
        };
        state
            .record_main_tool_result_with_class(
                owner,
                "call-edit-rework",
                "apply_patch",
                Some(ActionClass::Edit),
                true,
                "Success. Updated the following files:\nM generate_organization.py\n".to_string(),
            )
            .expect("rework edit records");
        let rerun_draft = ActionMapNextNodeDraft {
            kind: NodeKind::SmokeTest,
            title: "Run focused validation".to_string(),
            context_summary: "Run the organization validator after rework.".to_string(),
            dependency_node_ids: vec![rework_node_id.clone()],
        };
        state
            .finish_main_node_with_next(
                owner,
                &rework_node_id,
                "Reworked departmentSizes keys.".to_string(),
                None,
                Some(rerun_draft),
            )
            .expect("rework finishes into validation rerun");
        let rerun_validation_node_id = state
            .current_main_node_id
            .as_deref()
            .expect("validation rerun should be bound")
            .to_string();
        state
            .record_main_tool_result_with_class(
                owner,
                "call-test-pass",
                "shell_command",
                Some(ActionClass::Test),
                true,
                "pytest passed: 4 passed".to_string(),
            )
            .expect("successful validation records");
        let snapshot = ActionMapProviderRequestBudgetSnapshot {
            task_id: state.active_task_id.clone(),
            map_id: map_id.clone(),
            node_id: Some(rerun_validation_node_id.clone()),
            node_kind: Some(NodeKind::SmokeTest.as_str().to_string()),
            current_node_progress_signature: None,
            current_node_has_successful_edit: false,
            current_node_has_dependency_working_evidence: false,
            current_node_has_uncovered_mandatory_evidence: false,
            current_node_uncovered_mandatory_evidence: Vec::new(),
            current_node_validation_rework_artifacts: Vec::new(),
            route_mode: Some("deep".to_string()),
            profile_name: Some("taskspace-v005-deep".to_string()),
            request_phase: Some("validation_recovery".to_string()),
            provider_request_context_missing_reason: None,
            request_count: 16,
            max_requests: 20,
            node_request_count: 1,
            max_model_requests_per_node: 5,
            post_budget_grace_requests: 1,
            post_budget_grace_request_count: 0,
            budget_state: "normal".to_string(),
        };
        let (_, events) = state
            .force_finish_validation_after_successful_tool(
                owner,
                &snapshot,
                "validation_success_after_tool_drain",
            )
            .expect("forced closeout should run")
            .expect("successful validation should close out");

        assert!(events.iter().any(|event| {
            matches!(
                event,
                MapRuntimeEvent::ResultValidityChanged(changed)
                    if changed.result_id == blocker_result_id && changed.validity == "invalid"
            )
        }));
        let map = state.maps.get(&map_id).expect("active map");
        assert_eq!(
            map.results
                .get(&blocker_result_id)
                .expect("superseded blocker")
                .evidence_package
                .validity,
            ResultValidity::Invalid
        );
        state
            .record_main_final_response(owner, "Validation passed; the output is ready.")
            .expect("superseded blocker must not block final answer");
    }

    #[test]
    fn nested_validation_rework_can_edit_without_reviewing_prior_blocker_result() {
        let mut state = ActionMapRuntimeState::default();
        let owner = ThreadId::new();
        state.set_mode(MapRuntimeMode::Experiment);
        let (_, _, first_validation_node_id, _) = start_test_task_with_kind(
            &mut state,
            owner,
            NodeKind::SmokeTest,
            "Validate recovery",
            "Run the recovery script.",
            "Run smoke test",
            "Run python recover.py.",
            true,
        );
        state
            .record_main_tool_result_with_class(
                owner,
                "call-test-fail-1",
                "shell_command",
                Some(ActionClass::Test),
                false,
                "FileNotFoundError: recover.json missing after recover.py".to_string(),
            )
            .expect("first failed test records");
        let first_rework_node_id = state
            .current_main_node_id
            .as_deref()
            .expect("first failed validation should bind rework")
            .to_string();
        let first_blocker_result_id = {
            let map = state.active_map().expect("active map");
            map.nodes
                .get(&first_validation_node_id)
                .expect("first validation node")
                .result_context
                .iter()
                .find(|result_ref| result_ref.kind == NodeResultKind::Blocker)
                .expect("first blocker result")
                .id
                .clone()
        };
        state
            .record_main_tool_result_with_class(
                owner,
                "call-edit-rework-1",
                "apply_patch",
                Some(ActionClass::Edit),
                true,
                "patched recover.py to write recover.json".to_string(),
            )
            .expect("first rework edit records");
        let second_validation_draft = ActionMapNextNodeDraft {
            kind: NodeKind::SmokeTest,
            title: "Run focused validation".to_string(),
            context_summary: "Run recover.py again after rework.".to_string(),
            dependency_node_ids: vec![first_rework_node_id.clone()],
        };
        state
            .finish_main_node_with_next(
                owner,
                &first_rework_node_id,
                "first rework edit applied".to_string(),
                None,
                Some(second_validation_draft),
            )
            .expect("first rework finishes into second validation");
        state
            .record_main_tool_result_with_class(
                owner,
                "call-test-fail-2",
                "shell_command",
                Some(ActionClass::Test),
                false,
                "PermissionError: [WinError 5] access denied: 'trunc.db.recovered' in recover.py"
                    .to_string(),
            )
            .expect("second failed test records");
        let second_rework_node_id = state
            .current_main_node_id
            .as_deref()
            .expect("second failed validation should bind rework")
            .to_string();
        {
            let map = state.active_map().expect("active map");
            assert_eq!(
                map.results
                    .get(&first_blocker_result_id)
                    .expect("first blocker")
                    .evidence_package
                    .validity,
                ResultValidity::Unreviewed
            );
            assert_eq!(
                map.nodes
                    .get(&second_rework_node_id)
                    .expect("second rework")
                    .kind,
                NodeKind::ImplementSolution
            );
            let first_rework_result = map
                .results
                .values()
                .find(|result| {
                    result.node_id == first_rework_node_id && result.kind == NodeResultKind::Result
                })
                .expect("first rework lifecycle result");
            assert!(
                ActionMapRuntimeState::dependency_chain_contains_node(
                    map,
                    &second_rework_node_id,
                    &first_rework_node_id,
                ),
                "second rework should retain dependency-chain access to first rework"
            );
            assert!(
                state.unreviewed_result_is_active_rework_dependency_finish(
                    map,
                    first_rework_result,
                ),
                "first rework result should be treated as active nested rework input"
            );
        }

        state
            .prepare_main_tool_call(
                owner,
                ToolActionDescriptor::new(
                    "apply_patch",
                    ActionClass::Edit,
                    "*** Begin Patch\n*** Update File: recover.py\n*** End Patch",
                ),
            )
            .expect("nested rework edit should not be blocked by prior validation blocker");
    }

